// Check if card accessions match the current tree
function checkCardMatchingAccessions(cards, cardType, leaves) {
  if (!cards || cards.size === 0 || !leaves) return;
  
  // Cache leaves for efficient lookup
  const leafNames = new Set(leaves.map(leaf => normalizeAccession(leaf.data.name)));
  
  for (const [cardId, card] of cards) {
    let hasMatchingAccessions = false;
    
    // Check if card has accessions that match the current tree
    // Different card types store accessions differently
    if (cardType === 'dataframe' && card.accessions && card.accessions.size > 0) {
      // Dataframes store accessions in a Set
      for (const accession of card.accessions) {
        const normalizedAccession = normalizeAccession(accession);
        if (leafNames.has(normalizedAccession)) {
          hasMatchingAccessions = true;
          break;
        }
      }
    } else if ((cardType === 'heatmap' || cardType === 'chart' || cardType === 'highlight' || cardType === 'clade') && card.accessionToValue && card.accessionToValue.size > 0) {
      // Heatmaps, charts, highlights, and clades store accessions in accessionToValue Map
      for (const accession of card.accessionToValue.keys()) {
        const normalizedAccession = normalizeAccession(accession);
        if (leafNames.has(normalizedAccession)) {
          hasMatchingAccessions = true;
          break;
        }
      }
    } else if (card.data && card.data.byId && card.data.byId.size > 0) {
      // Some cards might store accessions in data.byId
      for (const accession of card.data.byId.keys()) {
        const normalizedAccession = normalizeAccession(accession);
        if (leafNames.has(normalizedAccession)) {
          hasMatchingAccessions = true;
          break;
        }
      }
    }
    
    // Update card display based on matching status
    const cardElement = document.getElementById(`${cardType}Card${cardId}`);
    if (cardElement) {
      if (!hasMatchingAccessions) {
        // No matching accessions - hide content and show warning
        hideCardContent(cardElement, cardId);
        showNoMatchMessage(cardElement, cardType);
        card.hasMatchingData = false;
      } else {
        // Has matching accessions - restore normal display
        showCardContent(cardElement, cardId);
        hideNoMatchMessage(cardElement);
        card.hasMatchingData = true;
      }
    }
  }
}

// Hide card content and show no match message
// Hide card content
function hideCardContent(cardElement, cardId) {
  // Hide all content except the title using CSS classes instead of inline styles
  const allLabels = cardElement.querySelectorAll('label');
  allLabels.forEach(label => {
    if (!label.querySelector(`#${cardElement.id.replace('Card', 'Title')}${cardId}`)) {
      label.classList.add('card-content-hidden');
    }
  });
  
  const allDivs = cardElement.querySelectorAll('div');
  allDivs.forEach(div => {
    if (div.querySelector('label') && !div.querySelector(`#${cardElement.id.replace('Card', 'Title')}${cardId}`)) {
      div.classList.add('card-content-hidden');
    }
  });
}

// Show card content
function showCardContent(cardElement, cardId) {
  // Remove hidden class to restore original styling
  const allLabels = cardElement.querySelectorAll('label');
  allLabels.forEach(label => {
    label.classList.remove('card-content-hidden');
  });
  
  const allDivs = cardElement.querySelectorAll('div');
  allDivs.forEach(div => {
    if (div.querySelector('label')) {
      div.classList.remove('card-content-hidden');
    }
  });
  
  // Special handling for chart cards to preserve chart type specific visibility
  if (cardElement.id.startsWith('chartCard')) {
    const chartId = cardElement.id.replace('chartCard', '');
    const chartTypeSelect = document.getElementById(`chartType${chartId}`);
    if (chartTypeSelect) {
      // Restore chart type specific visibility
      const selectedType = chartTypeSelect.value;
      const controlGroups = [
        `barControls${chartId}`,
        `lineControls${chartId}`, 
        `dotControls${chartId}`,
        `boxControls${chartId}`
      ];
      
      // Hide all control groups first
      controlGroups.forEach(groupId => {
        const group = document.getElementById(groupId);
        if (group) {
          group.style.display = 'none';
        }
      });
      
      // Show the appropriate control group
      const activeGroupId = `${selectedType}Controls${chartId}`;
      const activeGroup = document.getElementById(activeGroupId);
      if (activeGroup) {
        activeGroup.style.display = 'block';
      }
    }
  }
}

// Show no match message
function showNoMatchMessage(cardElement, cardType) {
  let noMatchDiv = cardElement.querySelector('.no-matching-data-message');
  if (!noMatchDiv) {
    noMatchDiv = document.createElement('div');
    noMatchDiv.className = 'no-matching-data-message';
    noMatchDiv.style.cssText = `
      text-align: center; 
      padding: 30px 20px; 
      color: var(--muted);
      border: 1px solid var(--ring);
      border-radius: 8px;
      margin: 10px;
      background: var(--chip);
    `;
    cardElement.appendChild(noMatchDiv);
  }
  
  noMatchDiv.innerHTML = `
    <i class="fas fa-exclamation-triangle" style="font-size: 32px; margin-bottom: 15px; color: var(--accent);"></i>
    <div style="font-weight: bold; margin-bottom: 8px; font-size: 16px;">No Matching Accessions</div>
    <div style="font-size: 14px; margin-bottom: 5px;">This ${cardType} contains no accessions that match the current tree.</div>
    <div style="font-size: 12px; color: var(--muted);">Load a different ${cardType} or tree file to see data.</div>
  `;
  noMatchDiv.style.display = 'block';
}

// Hide no match message
function hideNoMatchMessage(cardElement) {
  const noMatchDiv = cardElement.querySelector('.no-matching-data-message');
  if (noMatchDiv) {
    noMatchDiv.style.display = 'none';
  }
}

// Comprehensive cleanup function for new tree file
function resetAllFeaturesForNewTree() {
  labelsAutoHideDone = false;   // a new tree gets the large-tree default again
  
  // 1. Clear all selections and highlights
  highlightedClade = null;
  highlightedClades.clear();
  highlightedAccessions.clear();
  currentSearchTerm = '';
  
  // 2. Clear search input but keep clade toolbar visible
  const searchInput = document.getElementById('searchInput');
  if (searchInput) {
    searchInput.value = '';
    searchInput.classList.remove('has-text');
  }
  
  // 3. Keep all cards - only clear applied states
  
  // 4. Clear clade colors and background colors
  if (cladeColors) {
    cladeColors.clear();
  }
  if (cladeColorTs) {
    cladeColorTs.clear();
  }
  if (cladeBackgroundColors) {
    cladeBackgroundColors.clear();
  }
  
  // Clear permanent colors from tree nodes
  if (root) {
    root.descendants().forEach(node => {
      if (node.permanentColors) {
        node.permanentColors.clear();
      }
    });
  }
  
  // Clear global path leaf names storage
  if (window.pathLeafNames) {
    window.pathLeafNames.clear();
  }
  
  // 5. Clear all dropped nodes
  droppedNodes.clear();
  
  // 6. Clear all collapsed nodes
  collapsedNodes.clear();
  
  // 7. Clear all cartooned nodes
  cartoonedNodes.clear();
  
  // 8. Clear all rotated nodes
  nodeRotationCounts.clear();
  
  // 9. Clear gene-related states
  geneVisibility.clear();
  geneColors.clear();
  geneOrder = [];
  geneOrientation.clear();
  
  // 10. Clear alignment states
  alignByGeneEnabled = false;
  alignGeneName = '';
  alignType = 'left';
  
  // 11. Clear tree states
  root = null;
  originalRootNewick = null;
  lastKnownUserRoot = null;
  originalRoot = null;
  wasMidpointActive = false;
  
  // 12. Clear caches
  accessionCache.clear();
  ALIGNMENT_OPTIMIZATIONS.cache.clear();
  ALIGNMENT_OPTIMIZATIONS.lastProcessedFrame = null;
  
  // 13. Reset UI elements (but keep clade toolbar buttons)
  updateCladeButtonStates();
  updateMetadataLegend();
  updateResetRotationsButtonVisibility();
  updateResetCollapsesButtonVisibility();
  updateResetCartoonsButtonVisibility();
  updateRestoreDroppedButtonVisibility();
  updateResetHighlightsButtonVisibility();
  
  // Hide clade toolbar and clear button explicitly
  const cladeToolbar = document.getElementById('cladeToolbar');
  if (cladeToolbar) {
    cladeToolbar.classList.remove('visible');
  }
  
  const clearBtn = document.getElementById('clearCladeSelection');
  if (clearBtn) {
    clearBtn.style.display = 'none';
  }
  
  // Hide reset root button explicitly
  const resetRootBtn = document.getElementById('resetRoot');
  if (resetRootBtn) {
    resetRootBtn.style.display = 'none';
  }
  
  // 14. Keep all cards - only clear the applied states
  
  // 15. Reset section visibilities
  updateSectionVisibilities();
  
  // 16. Reset UI controls to defaults
  const metaAlignEnable = document.getElementById('metaAlignEnable');
  if (metaAlignEnable) {
    metaAlignEnable.checked = false;
  }
  
  const metaAlignGene = document.getElementById('metaAlignGene');
  if (metaAlignGene) {
    metaAlignGene.value = '';
    metaAlignGene.disabled = true;
  }
  
  const metaAlignTypeRadios = document.querySelectorAll('input[name="metaAlignType"]');
  metaAlignTypeRadios.forEach(radio => {
    radio.disabled = true;
    if (radio.value === 'left') radio.checked = true;
  });
  
  // 17. Clear status
  setStatus('');
  
}

async function handleTreeFile(f){
  try{
    // Reset ALL features for new tree
    resetAllFeaturesForNewTree();
    treeAxisTitle = '';   // the scale bar's title belongs to the tree
    
    // Reset font/truncation cache for new tree
    resetFontTruncationCache();
    
    // Show loading indicator for large files
    const fileSize = f.size;
    const isLargeFile = fileSize > 50000; // 50KB threshold for better performance
    
    // Clear accession cache for fresh start
    accessionCache.clear();
    
    if (isLargeFile) {
      setStatus(`Loading large tree file (${(fileSize/1024/1024).toFixed(1)}MB)...`);
    } else {
      setStatus('Loading tree file...');
    }
    
    // Time file reading
    let txt = await readFileAsText(f);
    try { txt = nexusToNewick(txt); }
    catch (e) { alert('Could not read this NEXUS file: ' + e.message); setStatus('Load a Newick tree'); return; }
    
    if (isLargeFile) {
      setStatus('Validating Newick format...');
    }
    
    // Time validation
    // Validate Newick format before parsing
    const validation = validateNewickFormat(txt);
    
    if (!validation.valid) {
      alert('Newick validation failed! Please check your file and try again.');
      setStatus('Load a Newick tree');
      return;
    }
    
    if (isLargeFile) {
      setStatus('Parsing tree structure...');
    }
    
    // Time parsing
    const newickStr = txt;   // the parser reads the first tree (up to its ';')
    
    // Declare timing variables outside try block so they're accessible in final summary
    let parseTime = 0;
    let hierarchyTime = 0;
    let processingTime = 0;
    let dataframeTime = 0;
    
    try {
      const obj = parseNewick(newickStr);
      
      // Store the original parsed object for serialization
      window.originalParsedTree = obj;
      
      if (isLargeFile) {
        setStatus('Converting to hierarchy...');
      }
      
      // Time hierarchy conversion
      root = toHierarchy(obj);
    
    // Time tree processing
    
    // Optimized processing for large trees
    if (isLargeFile) {
      setStatus('Processing tree properties...');
      
      // Combined processing: reset collapse state + process properties + save order in fewer traversals
      await processLargeTreeOptimized(root, (message) => {
        if (isLargeFile) setStatus(message);
      });
    } else {
      // Fast processing for smaller trees
      root.each(d=>{ d.children = d.children; d._children = null; });
      processTreeProperties(root);
      saveOriginalOrder(root);
    }
    
    // Store the original root for midpoint rooting functionality
    originalRoot = root;
    lastKnownUserRoot = root;
    
      if (isLargeFile) {
        setStatus('Finalizing tree setup...');
      }
      
      updateAddDataframeButtonVisibility();
      togglePanelCanvasVisibility(true);
      
      // Final status update
      const leafCount = root.leaves().length;
      if (isLargeFile) {
        setStatus(`Tree loaded successfully! ${leafCount} tips loaded.`);
      } else {
        setStatus(`Tree loaded: ${leafCount} tips`);
      }
      
    } catch (parseError) {
      console.error('Newick parsing error:', parseError);
      alert(`Newick parsing failed: ${parseError.message}\n\nPlease check your file format and try again.`);
      setStatus('Load a Newick tree');
      return;
    }
      
      // Time dataframe matching
      
      // Cache leaves to avoid multiple calls to root.leaves() - available for all card types
      const leaves = root.leaves();
      
      if(dataframes.size > 0) {
        // Optimized dataframe matching for large trees
        if (isLargeFile) {
          setStatus('Checking dataframe matches...');
        }
        let totalMatchingDataframes = 0;
        
        // Check each dataframe for matching accessions
        for(const [dataframeId, dataframe] of dataframes) {
          if(dataframe.meta && dataframe.meta.byId && dataframe.meta.byId.size > 0) {
            let hasMatchingAccessions = false;
            
            // Optimized matching: sample first 100 leaves for quick check
            const sampleSize = Math.min(100, leaves.length);
            for(let i = 0; i < sampleSize; i++) {
              const key = normalizeAccession(leaves[i].data.name);
              if(dataframe.meta.byId.has(key)) {
                hasMatchingAccessions = true;
                break;
              }
            }
            
            // If no matches in sample, do full check (but this is rare)
            if (!hasMatchingAccessions && sampleSize < leaves.length) {
              for(let i = sampleSize; i < leaves.length; i++) {
                const key = normalizeAccession(leaves[i].data.name);
                if(dataframe.meta.byId.has(key)) {
                  hasMatchingAccessions = true;
                  break;
                }
              }
            }
            
            // Update the dataframe card based on matching status
            const geneDiv = document.getElementById(`geneList${dataframeId}`);
            const operonDiv = document.getElementById(`operonList${dataframeId}`);
            const dataframeTitle = document.getElementById(`dataframeTitle${dataframeId}`);
            
        if(!hasMatchingAccessions) {
              // No matching accessions - hide all content and show single warning message
              const dataframeCard = document.getElementById(`dataframeCard${dataframeId}`);
              if(dataframeCard) {
                // Hide ALL content in the dataframe card using CSS classes
                const allLabels = dataframeCard.querySelectorAll('label');
                allLabels.forEach(label => {
                  // Skip the title label (contains the dataframe title and delete button)
                  if (!label.querySelector(`#dataframeTitle${dataframeId}`)) {
                    label.classList.add('card-content-hidden');
                  }
                });
                
                // Also hide any divs that contain sub-cards (like Alignment)
                const allDivs = dataframeCard.querySelectorAll('div');
                allDivs.forEach(div => {
                  // Hide divs that contain sub-cards (alignCard, etc.)
                  if (div.id && (div.id.includes('alignCard') || div.id.includes('operonCard') || div.id.includes('geneCard'))) {
                    div.classList.add('card-content-hidden');
                  }
                  // Hide parent divs that contain labels (like the Alignment container)
                  if (div.querySelector('label') && !div.querySelector(`#dataframeTitle${dataframeId}`)) {
                    div.classList.add('card-content-hidden');
                  }
                });
                
                // Create or update the no-matching-data message div
                let noMatchDiv = dataframeCard.querySelector('.no-matching-data-message');
                if (!noMatchDiv) {
                  noMatchDiv = document.createElement('div');
                  noMatchDiv.className = 'no-matching-data-message';
                  noMatchDiv.style.cssText = `
                    text-align: center; 
                    padding: 30px 20px; 
                    color: var(--muted);
                    border: 1px solid var(--ring);
                    border-radius: 8px;
                    margin: 10px;
                    background: var(--chip);
                  `;
                  dataframeCard.appendChild(noMatchDiv);
                }
                
                noMatchDiv.innerHTML = `
                  <i class="fas fa-exclamation-triangle" style="font-size: 32px; margin-bottom: 15px; color: var(--accent);"></i>
                  <div style="font-weight: bold; margin-bottom: 8px; font-size: 16px;">No Matching Accessions</div>
                  <div style="font-size: 14px; margin-bottom: 5px;">This dataframe contains no accessions that match the current tree.</div>
                  <div style="font-size: 12px; color: var(--muted);">Load a different dataframe or tree file to see data.</div>
                `;
                noMatchDiv.style.display = 'block';
              }
              
              // Update title to indicate no matching data
              if(dataframeTitle) {
                dataframeTitle.textContent = `Dataframe ${dataframeId}`;
              }
              
              // Store the mismatch state
              dataframe.hasMatchingData = false;
        } else {
              // Has matching accessions - restore normal display
              const dataframeCard = document.getElementById(`dataframeCard${dataframeId}`);
              if(dataframeCard) {
                // Show all the normal content sections using CSS classes
                const allLabels = dataframeCard.querySelectorAll('label');
                allLabels.forEach(label => {
                  label.classList.remove('card-content-hidden');
                });
                
                // Also show any divs that contain sub-cards (like Alignment)
                const allDivs = dataframeCard.querySelectorAll('div');
                allDivs.forEach(div => {
                  // Show divs that contain sub-cards (alignCard, etc.)
                  if (div.id && (div.id.includes('alignCard') || div.id.includes('operonCard') || div.id.includes('geneCard'))) {
                    div.classList.remove('card-content-hidden');
                  }
                  // Show parent divs that contain labels (like the Alignment container)
                  if (div.querySelector('label') && !div.querySelector(`#dataframeTitle${dataframeId}`)) {
                    div.classList.remove('card-content-hidden');
                  }
                });
                
                // Hide the no-matching-data message
                const noMatchDiv = dataframeCard.querySelector('.no-matching-data-message');
                if(noMatchDiv) {
                  noMatchDiv.style.display = 'none';
                }
              }
              
              if(dataframeTitle) {
                dataframeTitle.textContent = `Dataframe ${dataframeId}`;
              }
              
              // Store the match state
              dataframe.hasMatchingData = true;
              totalMatchingDataframes++;
              
              // Repopulate the dataframe card with current data
              populateDataframeCard(dataframeId, dataframe.meta);
            }
          }
        }
        
        // Show overall status message
        if(totalMatchingDataframes === 0) {
          setStatus('Warning: No dataframes have matching accessions with the new tree');
        } else if(totalMatchingDataframes < dataframes.size) {
          setStatus(`Warning: ${dataframes.size - totalMatchingDataframes} dataframe(s) have no matching accessions with the new tree`);
        } else {
          setStatus('All dataframes match the new tree');
        }
        
        // Update the gene legend to reflect the matching status
        updateMetadataLegend();
      }
      
      // Check other card types for matching accessions
      if (heatmaps && heatmaps.size > 0) {
        checkCardMatchingAccessions(heatmaps, 'heatmap', leaves);
      }
      
      if (charts && charts.size > 0) {
        checkCardMatchingAccessions(charts, 'chart', leaves);
      }
      
      if (highlights && highlights.size > 0) {
        checkCardMatchingAccessions(highlights, 'highlight', leaves);
      }
      
      if (clades && clades.size > 0) {
        checkCardMatchingAccessions(clades, 'clade', leaves);
      }
      
    // Ensure tree branch colors match the current theme
    updateTreeBranchColors();
    
    // Apply clade colors to tree branches after reassessment
    applyCladeColorsToTree();
    
    // Redraw tree to reflect all reassessment changes
    drawTree();
    
    // onFitToViewRect();
    
  }catch(e){ setStatus('Tree parse error: '+e.message); console.error(e);   }
}

