// --- Dataframe related functions starts here ---

function sortGenesByStartValues(genes, metadata) {
  if (!metadata || !metadata.rows || !metadata.columns || metadata.columns.length < 3) {
    return genes;
  }
  
  const columnIndices = getDataframeColumnIndices(metadata);
  const { geneCol, startCol } = columnIndices;
  
  const geneStartValues = new Map();
  
  // OPTIMIZATION: Pre-build a map of gene -> rows to avoid repeated filtering
  const geneRowsMap = new Map();
  
  // Single pass through all rows to build the map
  metadata.rows.forEach(row => {
    const gene = row[geneCol];
    if (gene) {
      if (!geneRowsMap.has(gene)) {
        geneRowsMap.set(gene, []);
      }
      geneRowsMap.get(gene).push(row);
    }
  });
  
  // Process each gene using the pre-built map
  genes.forEach(gene => {
    const geneRows = geneRowsMap.get(gene) || [];
    if (geneRows.length > 0) {
      const startValues = geneRows
        .map(row => +row[startCol])
        .filter(val => Number.isFinite(val));
      
      if (startValues.length > 0) {
        const avgStart = startValues.reduce((sum, val) => sum + val, 0) / startValues.length;
        geneStartValues.set(gene, avgStart);
      }
    }
  });
  
  // Sort genes
  const sortedGenes = genes.slice().sort((a, b) => {
    const aIsLength = String(a).toLowerCase() === 'length';
    const bIsLength = String(b).toLowerCase() === 'length';
    
    if (aIsLength && !bIsLength) return -1;
    if (!aIsLength && bIsLength) return 1;
    
    const aStart = geneStartValues.get(a) || 0;
    const bStart = geneStartValues.get(b) || 0;
    
    return bStart - aStart;
  });
  
  return sortedGenes;
}

async function handleUnifiedMetadataLoad(f, parsedMetadata, isFirstLoad) {
  const isPlaceholderState = dataframes.size === 0 && !getFirstDataframeMeta();
  
  // Step 1: Create dataframe card
  const newCardId = createNewDataframeCard(parsedMetadata);
  
  if (newCardId) {
    const df = dataframes.get(newCardId);
    if (df && !df.meta) {
      df.meta = parsedMetadata;
      df.selectedMetaFile = f;
    }
    
    // Step 2: Add dataframe to panel system
    // Always call addDataframe() to update panel system when adding a dataframe
    if (typeof addDataframe === 'function') {
      addDataframe();
    }
    
    if (isFirstLoad) {
      selectedMetaFile = f;
      if (metaTitleEl) metaTitleEl.textContent = 'Dataframe 1';
      
      // Step 3: Gene processing
      if (parsedMetadata.columns && parsedMetadata.columns.length > 1) {
        // Use detected gene column instead of hardcoded position
        const columnIndicesLoad = getDataframeColumnIndices(parsedMetadata);
        const geneCol = columnIndicesLoad.geneCol;
        
        // Extract unique genes from all rows
        let genes = Array.from(new Set(parsedMetadata.rows.map(r => r[geneCol]).filter(Boolean)));
        
        // Sort genes by start values
        genes = sortGenesByStartValues(genes, parsedMetadata);
        
        // Assign colors and setup gene properties
        const assignedColors = assignColors(genes, 'gene', newCardId);
        geneOrder = [...genes];
        genes.forEach((g, i) => {
          const gl = String(g).toLowerCase();
          geneVisibility.set(g, true);
          geneColors.set(g, gl === 'length' ? '#9ca3af' : ((df && df.geneColors.get(g)) || assignedColors.get(g)));
          geneOrientation.set(g, false);
        });
      }
      
      // Step 4: Fit to view
      // onFitToViewRect();
    }
    
    // Step 5: Update legend
    updateMetadataLegend();
    
    // Step 6: Redraw tree
    // if (root) {
    //   drawTree();
    //   console.log('drawTree in handleUnifiedMetadataLoad');
    // }
  }
}

async function handleMetaFile(f){
  try{
    // Allow duplicate file loading - same file can be loaded multiple times
    
    // Step 1: File reading
    const txt = await readFileAsText(f);
    
    // Step 2: Format validation
    const validation = validateDataframeFormat(txt);
    
    if (!validation.valid) {
      const userConfirmed = confirm(`Dataframe format validation failed!\n\n${validation.error}\n\nThis might be the wrong format. Would you like to proceed anyway?`);
      if (!userConfirmed) {
        setStatus('Dataframe loading cancelled by user');
        return;
      }
      // User chose to continue despite validation failure
      setStatus('Proceeding with dataframe loading despite format issues...');
    }
    
    // Step 3: Table parsing (most expensive operation)
    const parsedMetadata = parseTable(txt);
    
    // Step 4: Accession matching
    let hasMatchingAccessions = false;
    if(root && parsedMetadata && parsedMetadata.byId && parsedMetadata.byId.size > 0) {
      const leaves = root.leaves();
      
      for(const leaf of leaves) {
        const key = normalizeAccession(leaf.data.name);
        if(parsedMetadata.byId.has(key)) {
          hasMatchingAccessions = true;
          break;
        }
      }
    }
    
    // Step 5: UI processing
    const existingDataframeCards = document.querySelectorAll('.dataframe-panel');
    const isFirstLoad = !getFirstDataframeMeta();
    await handleUnifiedMetadataLoad(f, parsedMetadata, isFirstLoad);
    
  }catch(e){ setStatus('Metadata parse error: '+e.message); console.error(e); }
}

function updateDataframeOrder() {
  const cards = Array.from(document.querySelectorAll('.dataframe-panel'));
  const newOrder = cards.map(card => {
    const ds = card.getAttribute('data-dfid');
    if (ds && /^\d+$/.test(ds)) return parseInt(ds, 10);
    const m = (card.id || '').match(/dataframeCard(\d+)/);
    return m ? parseInt(m[1], 10) : null;
  }).filter(Number.isFinite);
  
  // Update the dataframes map to reflect the new order
  const newDataframes = new Map();
  newOrder.forEach((id, index) => {
    const dataframe = dataframes.get(id);
    if (dataframe) {
      const newId = index + 1;
      dataframe.id = newId; // Update the dataframe's id property
      newDataframes.set(newId, dataframe);
    }
  });
  
  // Replace the dataframes map
  dataframes.clear();
  for (const [id, dataframe] of newDataframes) {
    dataframes.set(id, dataframe);
  }
  
  // Clear alignment cache since dataframe IDs have changed
  if (ALIGNMENT_OPTIMIZATIONS && ALIGNMENT_OPTIMIZATIONS.cache) {
    ALIGNMENT_OPTIMIZATIONS.cache.clear();
  }
  
  // Update DOM elements to match the new order and IDs
  const dataframeContainer = document.getElementById('dataframeContainer');

  if (dataframeContainer && Array.isArray(newOrder)) {
    newOrder.forEach((oldId, index) => {
      const newId = index + 1;
      const el = document.getElementById(`dataframeCard${oldId}`);
      if (el) {
        // Update the card ID and data-dfid
        el.id = `dataframeCard${newId}`;
        el.setAttribute('data-dfid', String(newId));
        
          // Update all child elements
          const elementsToUpdate = [
            `dataframeSummary${oldId}`, `dataframeTitle${oldId}`, `deleteDataframe${oldId}`,
            `trackWidth${oldId}`, `geneList${oldId}`, `orderSelect${oldId}`, `geneSelect${oldId}`,
            `orientationSelect${oldId}`, `colorSelect${oldId}`, `alignBars${oldId}`, `geneAlign${oldId}`, `alignType${oldId}`,
            `operonMasterToggle${oldId}`, `operonList${oldId}`, `metaAlignEnable${oldId}`, `metaAlignGene${oldId}`,
            `metaAlignType${oldId}`, `showMajorGrid${oldId}`, `dashedMajorGrid${oldId}`, `majorGridWidth${oldId}`,
            `showMinorGrid${oldId}`, `dashedMinorGrid${oldId}`, `minorGridWidth${oldId}`
          ];

          elementsToUpdate.forEach(oldElementId => {
            const element = document.getElementById(oldElementId);
            if (element) {
              const newElementId = oldElementId.replace(oldId, newId);
              element.id = newElementId;
              
              // Update title text content
              if (oldElementId === `dataframeTitle${oldId}`) {
                element.textContent = `Dataframe ${newId}`;
              }
              
              if (oldElementId === `deleteDataframe${oldId}`) {
                // Remove all existing event listeners by cloning the element
                const newElement = element.cloneNode(true);
                element.parentNode.replaceChild(newElement, element);
                
                // Add the new event listener with the correct ID
                newElement.addEventListener('click', (ev) => {
            ev.preventDefault();
            ev.stopPropagation();
            deleteDataframeCard(newId);
          });
        }
        
        // Re-bind event listeners for grid controls
        if (oldElementId === `showMajorGrid${oldId}`) {
          const newElement = element.cloneNode(true);
          element.parentNode.replaceChild(newElement, element);
          newElement.addEventListener('change', (ev) => {
            updateDataframeShowMajorGrid(newId, ev.target.checked);
          });
        } else if (oldElementId === `dashedMajorGrid${oldId}`) {
          const newElement = element.cloneNode(true);
          element.parentNode.replaceChild(newElement, element);
          newElement.addEventListener('change', (ev) => {
            updateDataframeDashedMajorGrid(newId, ev.target.checked);
          });
        } else if (oldElementId === `majorGridWidth${oldId}`) {
          const newElement = element.cloneNode(true);
          element.parentNode.replaceChild(newElement, element);
          newElement.addEventListener('input', (ev) => {
            updateDataframeMajorGridWidth(newId, parseFloat(ev.target.value));
          });
        } else if (oldElementId === `showMinorGrid${oldId}`) {
          const newElement = element.cloneNode(true);
          element.parentNode.replaceChild(newElement, element);
          newElement.addEventListener('change', (ev) => {
            updateDataframeShowMinorGrid(newId, ev.target.checked);
          });
        } else if (oldElementId === `dashedMinorGrid${oldId}`) {
          const newElement = element.cloneNode(true);
          element.parentNode.replaceChild(newElement, element);
          newElement.addEventListener('change', (ev) => {
            updateDataframeDashedMinorGrid(newId, ev.target.checked);
          });
        } else if (oldElementId === `minorGridWidth${oldId}`) {
          const newElement = element.cloneNode(true);
          element.parentNode.replaceChild(newElement, element);
          newElement.addEventListener('input', (ev) => {
            updateDataframeMinorGridWidth(newId, parseFloat(ev.target.value));
          });
        }
            }
          });

          // Move the card to correct position in dataframe container
          dataframeContainer.appendChild(el);
      }
    });
  }
  
  // Update panel system to reflect new order
  updatePanelSystemAfterDeletion();
  
  // Redraw the tree
  // if (root) {
  //   drawTree();
  //   console.log('drawTree in updateDataframeOrder');
  // }
}

function addDataframe() {
  if (panelCount >= 20) return;
    
  // Calculate proper panel count based on current panels
  const heatmapPanels = Array.from(document.querySelectorAll('.heatmap-panel'));
  const dataframePanels = Array.from(document.querySelectorAll('.dataframe-panel'));
  const chartPanels = Array.from(document.querySelectorAll('.chart-panel'));
  const heatmapPanelCount = heatmapPanels.length;
  const currentDataframePanelCount = dataframePanels.length;
  const chartPanelCount = chartPanels.length;
    
  // Account for the dataframe being added
  // CRITICAL: Only add 1 if we don't already have a dataframe panel
  const dataframePanelCount = currentDataframePanelCount === 0 ? 1 : currentDataframePanelCount;
  
  // Check if we need a placeholder panel (when no dataframes AND no charts exist)
  // But if we're adding a dataframe, we don't need a placeholder
  const needsPlaceholder = currentDataframePanelCount === 0 && chartPanelCount === 0 && false; // Never need placeholder when adding dataframe
  
  // Calculate new panel count: Tree + Labels + Placeholder(if needed) + Heatmaps + Dataframes + Charts
  const newPanelCount = 2 + (needsPlaceholder ? 1 : 0) + heatmapPanelCount + dataframePanelCount + chartPanelCount + msaPanelCount();
    
  // CRITICAL: Only update panelCount if it's not already correct
  if (panelCount !== newPanelCount) {
    window.panelCount = newPanelCount;
    panelCount = newPanelCount;
  } 
  
  const svg = document.getElementById('svg');
  if (!svg) return;
  
  const totalSplitterWidth = (panelCount - 1) * SPLITTER_WIDTH;
  const availableWidth = svg.clientWidth - totalSplitterWidth - groupMarksReserve();
  const OLD_TREE_WIDTH = 160;
  const hideLabelsEl = document.getElementById('hideLabels');
  const hideLabels = hideLabelsEl && hideLabelsEl.checked;
  const OLD_LABEL_WIDTH = hideLabels ? 0 : 80;
  const OLD_MARGIN_LEFT = 40;
  
  // Don't calculate panel widths here - let initializePanels() handle it
  // Just update the panel count and let the system recalculate everything
  initializePanels();
  updatePanelHeights();
  
  // Metadata panel boundaries are calculated in initializePanels()
  
  setTimeout(() => {
    if (typeof drawTree === 'function') {
      drawTree();
      updateZoomBounds();
    }
  }, 0);
}

function updateAddDataframeButtonVisibility() {
  const container = document.getElementById('addDataframeContainer');
  const button = document.getElementById('addDataframe');
  const subcardButton = document.getElementById('addDataframeOption');
  
  if (container && button) {
    container.style.display = root ? 'flex' : 'none';
    
    if (root) {
      const dataframeCount = dataframes.size;
      const maxDataframes = 4;
      
      // Keep the main button always enabled
        button.disabled = false;
        button.style.opacity = '1';
        button.style.cursor = 'pointer';
        button.style.background = 'rgba(20,184,166,0.12)';
        button.style.color = 'var(--accent)';
        button.style.border = '1px solid var(--ring)';
        button.title = 'Add a new dataframe';
      
      // Only disable the subcard button when at max dataframes
      if (dataframeCount >= maxDataframes) {
        if (subcardButton) {
          subcardButton.disabled = true;
          subcardButton.style.opacity = '0.5';
          subcardButton.style.cursor = 'not-allowed';
          subcardButton.title = `Maximum ${maxDataframes} dataframes allowed. Remove a dataframe to add more.`;
        }
      } else {
        if (subcardButton) {
          subcardButton.disabled = false;
          subcardButton.style.opacity = '1';
          subcardButton.style.cursor = 'pointer';
          subcardButton.title = 'Add Dataframe';
        }
      }
    }
    
    setTimeout(() => {
      updateSidebarHeight();
    }, 10);
  }
}

