function createNewHeatmapCard(heatmapData) {
  // Get existing heatmap IDs to determine next ID
  const existingIds = Array.from(document.querySelectorAll('.heatmap-panel'))
    .map(n => {
      const m = (n.id || '').match(/heatmapCard(\d+)/);
      return m ? parseInt(m[1], 10) : NaN;
    })
    .filter(Number.isFinite);
  
  const nextId = existingIds.length ? Math.max(...existingIds) + 1 : 1;
  const heatmapId = nextId;
  
  const cardId = `heatmapCard${heatmapId}`;
  
  // Create the new heatmap card HTML
  const newCard = document.createElement('details');
  newCard.id = cardId;
  newCard.className = 'heatmap-panel';
  newCard.setAttribute('data-hmid', String(heatmapId));
  newCard.setAttribute('draggable', 'true');
  
  // Close ALL open tabs in the sidebar to ensure only one tab is expanded at a time
  const allOpenTabs = document.querySelectorAll('aside details[open]');
  allOpenTabs.forEach(tab => {
    tab.removeAttribute('open');
  });
  
  // Now open the new card
  newCard.setAttribute('open', '');
  
  newCard.innerHTML = `
    <summary id="heatmapSummary${heatmapId}" class="df-summary">
      <span class="pro-card-badge pro-badge-heatmap" aria-hidden="true">HM</span>
      <span id="heatmapTitle${heatmapId}" class="pro-card-title">Heatmap ${heatmapId}</span>
      <span class="df-spacer"></span>
      <button id="deleteHeatmap${heatmapId}" class="df-delete" title="Remove heatmap" aria-label="Remove heatmap"></button>
      <span class="drag-handle" title="Drag to reorder heatmaps" aria-hidden="true"></span>
    </summary>
    <div class="section row2 pro-card-body">
      <div class="pro-card-section">
        <label class="pro-row"><span>Show heatmap</span><input type="checkbox" id="heatmapToggle${heatmapId}" class="heatmap-toggle pro-switch" checked></label>
        <div class="pro-card-head"><span class="pro-section-title">Values</span></div>
        <div id="heatmapData${heatmapId}" class="pro-list"><i>Heatmap data loaded</i></div>
      </div>
    </div>
  `;
  
  // Insert the new card in the heatmap container
  const heatmapContainer = document.getElementById('heatmapContainer');
  if (!heatmapContainer) {
    return null;
  }
  
  // Simply append to the heatmap container
  heatmapContainer.appendChild(newCard);
  
  // Update section visibility
  updateSectionVisibilities();
  
  // Add event listener for delete button
  const deleteBtn = newCard.querySelector(`#deleteHeatmap${heatmapId}`);
  deleteBtn.addEventListener('click', (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    deleteHeatmapCard(heatmapId);
  });
  
  // Store heatmap data using a separate Map
  if (!heatmaps) {
    heatmaps = new Map();
  }
  heatmaps.set(heatmapId, {
    id: heatmapId,
    data: heatmapData,
    visible: true,
    type: 'heatmap'
  });
  
  // Sync radial panels if in radial mode
  if (window.radialPanelSystem && geometry === 'radial') {
    window.radialPanelSystem.sync();
  }
  
  return heatmapId;
}

async function handleHeatmapFile(f){
  try{
    const txt = await readFileAsText(f);
    const parsedHeatmapData = parseTable(txt);
    
    // Check if any accessions match between tree and heatmap data
    let hasMatchingAccessions = false;
    if(root && parsedHeatmapData && parsedHeatmapData.byId && parsedHeatmapData.byId.size > 0) {
      const leaves = root.leaves();
      for(const leaf of leaves) {
        const key = normalizeAccession(leaf.data.name);
        if(parsedHeatmapData.byId.has(key)) {
          hasMatchingAccessions = true;
          break;
        }
      }
    }
    
    // Create heatmap card
    const newCardId = createNewHeatmapCard(parsedHeatmapData);
    
    if (newCardId) {
      // Store the matching status in the heatmap data
      const hm = heatmaps.get(newCardId);
      if (hm) {
        hm.hasMatchingData = hasMatchingAccessions;
      }
      
      // Populate the heatmap card
      populateHeatmapCard(newCardId, parsedHeatmapData);
      setStatus(`Heatmap loaded: ${f.name}`);
      
      // Add heatmap panel to canvas
      addHeatmap();
      
      // Update legend to show heatmap legend
      updateMetadataLegend();
      
      // Redraw tree after legend update to ensure panel positions are correct
      if (root) {
        // drawTree();
        // console.log('drawTree in handleHeatmapFile called but suppressed by user');
      }
    }
    
  }catch(e){ setStatus('Heatmap parse error: '+e.message); console.error(e); }
}

// a heatmap cell's colour and whether it is drawn: a numeric column on its gradient
// (heatmap-scale.js), else the value's own colour and visibility
function heatmapColorOf(hm, value) {
  return (window.tmHeatScale && tmHeatScale.isGradient(hm)) ? tmHeatScale.colorFor(hm, value) : hm.valueColors.get(value);
}
function heatmapValueShown(hm, value) {
  if (!value) return false;
  if (window.tmHeatScale && tmHeatScale.isGradient(hm)) return true;
  return !!hm.valueVisibility.get(value);
}
function populateHeatmapCard(heatmapId, metadata) {
  // Store the heatmap data
  if (!heatmaps) {
    heatmaps = new Map();
  }
  
  let hm = heatmaps.get(heatmapId);
  if (!hm) {
    // Create new heatmap entry if it doesn't exist
    hm = {
      id: heatmapId,
      data: metadata,
      visible: true,
      type: 'heatmap'
    };
    heatmaps.set(heatmapId, hm);
  } else {
    hm.data = metadata;
    hm.type = 'heatmap';
  }
  
  // Extract unique values from the second column (value column)
  const uniqueValues = new Set();
  const accessionToValue = new Map();
  
  if (metadata.rows && metadata.rows.length > 0) {
    metadata.rows.forEach((row, index) => {
      // row is an object, not an array
      const columns = metadata.columns || [];
      if (columns.length >= 2) {
        const accession = row[columns[0]]; // First column: molecule/accession
        const value = String(row[columns[1]]); // Second column: value (character or number)
        
        if (accession && value) {
          uniqueValues.add(value);
          accessionToValue.set(accession, value);
        }
      }
    });
  }
  
  // Initialize heatmap data structure if not exists
  if (!hm) {
    heatmaps.set(heatmapId, {
      id: heatmapId,
      data: metadata,
      visible: true,
      type: 'heatmap',
      uniqueValues: Array.from(uniqueValues).sort(naturalCompare),
      accessionToValue: accessionToValue,
      valueVisibility: new Map(),
      valueColors: new Map()
    });
  } else {
    hm.uniqueValues = Array.from(uniqueValues).sort(naturalCompare);
    hm.accessionToValue = accessionToValue;
    if (!hm.valueVisibility) hm.valueVisibility = new Map();
    if (!hm.valueColors) hm.valueColors = new Map();
  }
  
  // Assign colors to unique values using intelligent color assignment
  const sortedValues = Array.from(uniqueValues).sort(naturalCompare);
  const gradient = !!(window.tmHeatScale && tmHeatScale.isGradient(hm));
  if (!gradient) {
    const assignedColors = assignColors(sortedValues, 'heatmap', heatmapId);
    sortedValues.forEach((value, index) => {
      if (!hm.valueVisibility.has(value)) {
        hm.valueVisibility.set(value, true); // Default to visible
      }
      if (!hm.valueColors.has(value)) {
        hm.valueColors.set(value, assignedColors.get(value));
      }
    });
  }
  
  // Populate the heatmap data display with value list
  const heatmapDiv = document.getElementById(`heatmapData${heatmapId}`);
  
  if (heatmapDiv && gradient && hm.hasMatchingData !== false) {
    tmHeatScale.renderControls(heatmapId, hm);
  } else if (heatmapDiv) {
    heatmapDiv.classList.remove('hs-box');
    const head = heatmapDiv.previousElementSibling && heatmapDiv.previousElementSibling.querySelector('.pro-section-title');
    if (head) head.textContent = 'Values';
    // Check if this heatmap has matching accessions - if not, show warning message
    if (hm.hasMatchingData === false) {
      // Show no matching accessions message
      heatmapDiv.innerHTML = `
        <div style="text-align: center; padding: 20px; color: var(--muted);">
          <div style="font-weight: bold; color: var(--destructive); margin-bottom: 8px;">
            ⚠️ No matching accessions found
          </div>
          <div style="font-size: 11px;">
            Heatmap ${heatmapId} doesn't match current tree
          </div>
        </div>
      `;
    } else if (sortedValues.length > 0) {
      const canGradient = window.tmHeatScale && tmHeatScale.stats(hm).numeric;
      heatmapDiv.innerHTML = (canGradient ? `<div class="hs-mode pro-row"><span>Scale</span><span class="pro-radio-seg" role="radiogroup" aria-label="Heatmap scale"><label><input type="radio" name="hsMode${heatmapId}" class="hs-mode-radio" value="gradient"><span>Gradient</span></label><label><input type="radio" name="hsMode${heatmapId}" class="hs-mode-radio" value="categories" checked><span>Categories</span></label></span></div>` : '') + `
        ${sortedValues.map(value => {
          const checked = hm.valueVisibility.get(value) ? 'checked' : '';
          const color = hm.valueColors.get(value) || '#ccc';
          return `<div class="heatmap-value-card pro-list-row" data-value="${value}">
                    <input type="checkbox" class="heatmap-value-toggle pro-check" data-value="${value}" ${checked} aria-label="Show ${value}">
                    <span class="heatmap-value-name pro-list-name" title="${value}">${value}</span>
                    <input type="color" class="heatmap-value-color pro-swatch" data-value="${value}" value="${color}" title="Colour" aria-label="Colour of ${value}">
                  </div>`;
        }).join('')}
      `;
    } else {
      heatmapDiv.innerHTML = '<i>No heatmap data available</i>';
    }
    
    // Add event listeners for checkboxes
    heatmapDiv.querySelectorAll('.heatmap-value-toggle').forEach(checkbox => {
      checkbox.addEventListener('change', ev => {
        const value = ev.target.getAttribute('data-value');
        hm.valueVisibility.set(value, ev.target.checked);
        
        // Update master checkbox state based on individual checkboxes
        updateHeatmapMasterCheckbox(heatmapId);
        
        // Update legend to reflect visibility changes
        updateMetadataLegend();
        
        // Redraw tree to update heatmap display
        if (root) {
          drawTree();
        }
      });
    });
    
    // Add event listener for master checkbox
    const masterCheckbox = document.getElementById(`heatmapToggle${heatmapId}`);
    if (masterCheckbox) {
      masterCheckbox.addEventListener('change', ev => {
        const isChecked = ev.target.checked;
        
        // Update all individual checkboxes to match master checkbox
        heatmapDiv.querySelectorAll('.heatmap-value-toggle').forEach(checkbox => {
          checkbox.checked = isChecked;
          const value = checkbox.getAttribute('data-value');
          hm.valueVisibility.set(value, isChecked);
        });
        
        // Update legend to reflect visibility changes
        updateMetadataLegend();
        
        // Redraw tree to update heatmap display
        if (root) {
          drawTree();
        }
      });
    }
    
    // Add event listeners for color pickers
    heatmapDiv.querySelectorAll('.heatmap-value-color').forEach(colorPicker => {
      colorPicker.addEventListener('input', ev => {
        const value = ev.target.getAttribute('data-value');
        hm.valueColors.set(value, ev.target.value);
        
        // Update legend to reflect color changes
        updateMetadataLegend();
        
        // Redraw tree to update heatmap display
        if (root) {
          drawTree();
        }
      });
    });
    
    // Initialize master checkbox state
    updateHeatmapMasterCheckbox(heatmapId);
  } else {
    heatmapDiv.innerHTML = '<i>No heatmap data available</i>';
  }
}

function deleteHeatmapCard(heatmapId) {
  // Hide the subcard if it's open
  const addDataframeSubcard = document.getElementById('addDataframeSubcard');
  const addDataframeBtn = document.getElementById('addDataframe');
  if (addDataframeSubcard && addDataframeBtn) {
    addDataframeSubcard.style.display = 'none';
    addDataframeBtn.classList.remove('active');
  }
  
  const heatmapPanels = Array.from(document.querySelectorAll('.heatmap-panel'));
  const panelIndex = heatmapPanels.findIndex(panel => {
    const hm = panel.getAttribute('data-hmid');
    if (hm && /^\d+$/.test(hm)) return parseInt(hm, 10) === heatmapId;
    const m = (panel.id || '').match(/heatmapCard(\d+)/);
    return m && parseInt(m[1], 10) === heatmapId;
  });
  
  if (panelIndex >= 0) {
    const panel = heatmapPanels[panelIndex];
    panel.remove();
    
    // Remove from heatmaps Map
    if (heatmaps) {
      heatmaps.delete(heatmapId);
    }
    
    // Reindex remaining heatmap panels
    const remainingPanels = Array.from(document.querySelectorAll('.heatmap-panel'));
    remainingPanels.forEach((panel, index) => {
      const newId = index + 1;
      const oldId = panel.getAttribute('data-hmid') || 
                   (panel.id.match(/heatmapCard(\d+)/) && parseInt(panel.id.match(/heatmapCard(\d+)/)[1], 10));
      
      if (oldId && newId !== oldId) {
        // Update panel attributes
        panel.setAttribute('data-hmid', newId);
        panel.id = `heatmapCard${newId}`;
        
        // Update all child elements
        const elementsToUpdate = [
          `heatmapSummary${oldId}`, `heatmapTitle${oldId}`, `deleteHeatmap${oldId}`,
          `heatmapToggle${oldId}`, `heatmapData${oldId}`
        ];
        
        elementsToUpdate.forEach(oldElementId => {
          const element = document.getElementById(oldElementId);
          if (element) {
            const newElementId = oldElementId.replace(oldId, newId);
            element.id = newElementId;
            
            // Update title text content
            if (oldElementId === `heatmapTitle${oldId}`) {
              element.textContent = `Heatmap ${newId}`;
            }
            
            if (oldElementId === `deleteHeatmap${oldId}`) {
              // Remove all existing event listeners by cloning the element
              const newElement = element.cloneNode(true);
              element.parentNode.replaceChild(newElement, element);
              
              // Add the new event listener with the correct ID
              newElement.addEventListener('click', (ev) => {
                ev.preventDefault();
                ev.stopPropagation();
                deleteHeatmapCard(newId);
              });
            }
          }
        });
      }
    });
    
    // Reindex the heatmaps Map
    if (heatmaps && heatmaps.size > 0) {
      const newHeatmaps = new Map();
      let newIndex = 1;
      heatmaps.forEach((value, key) => {
        if (key !== heatmapId) {
          newHeatmaps.set(newIndex, value);
          newIndex++;
        }
      });
      heatmaps = newHeatmaps;
    }
    
    // Update panel system to reflect heatmap deletion
    updatePanelSystemAfterDeletion();
    
    // Update legend to hide heatmap legend if no heatmaps remain
    updateMetadataLegend();
    
    // Update section visibility
    updateSectionVisibilities();
    
    // Redraw tree after legend update to ensure panel positions are correct
    // if (root) {
    //   drawTree();
    //   console.log('drawTree in deleteHeatmapCard');
    // }
  }
}

function updateHeatmapOrder() {
  const cards = Array.from(document.querySelectorAll('.heatmap-panel'));
  const newOrder = cards.map(card => {
    const ds = card.getAttribute('data-hmid');
    if (ds && /^\d+$/.test(ds)) return parseInt(ds, 10);
    const m = (card.id || '').match(/heatmapCard(\d+)/);
    return m ? parseInt(m[1], 10) : null;
  }).filter(Number.isFinite);
  
  // Update the heatmaps map to reflect the new order
  const newHeatmaps = new Map();
  newOrder.forEach((id, index) => {
    const heatmap = heatmaps.get(id);
    if (heatmap) {
      const newId = index + 1;
      newHeatmaps.set(newId, heatmap);
    }
  });
  
  // Replace the heatmaps map
  heatmaps.clear();
  for (const [id, heatmap] of newHeatmaps) {
    heatmaps.set(id, heatmap);
  }
  
  // Update DOM elements to match the new order and IDs
  const heatmapContainer = document.getElementById('heatmapContainer');

  if (heatmapContainer && Array.isArray(newOrder)) {
    
    newOrder.forEach((oldId, index) => {
      const newId = index + 1;
      const el = document.getElementById(`heatmapCard${oldId}`);
      if (el) {
        // Update the card ID and data-hmid
        el.id = `heatmapCard${newId}`;
        el.setAttribute('data-hmid', String(newId));
        
        // Update the card title
        const titleEl = document.getElementById(`heatmapTitle${oldId}`);
        if (titleEl) {
          titleEl.id = `heatmapTitle${newId}`;
          titleEl.textContent = `Heatmap ${newId}`;
        }
        
        // Update the delete button ID and event listener
        const deleteBtn = document.getElementById(`deleteHeatmap${oldId}`);
        if (deleteBtn) {
          deleteBtn.id = `deleteHeatmap${newId}`;
          // Remove old event listener by cloning
          const newDeleteBtn = deleteBtn.cloneNode(true);
          deleteBtn.parentNode.replaceChild(newDeleteBtn, deleteBtn);
          // Add new event listener
          newDeleteBtn.addEventListener('click', (ev) => {
            ev.preventDefault();
            ev.stopPropagation();
            deleteHeatmapCard(newId);
          });
        }

        // Move card to correct position in heatmap container
        heatmapContainer.appendChild(el);
      }
    });
  }
  
  // Update panel system to reflect new order
  updatePanelSystemAfterDeletion();
  
  // Redraw the tree
  // if (root) {
  //   drawTree();
  // console.log('drawTree in updateHeatmapOrder');
  // }
}

function addHeatmap() {
  if (panelCount >= 20) return; // Increased limit to accommodate more heatmaps + dataframes
  
  panelCount++;
  
  const svg = document.getElementById('svg');
  if (!svg) return;
  
  const totalSplitterWidth = (panelCount - 1) * SPLITTER_WIDTH;
  const availableWidth = svg.clientWidth - totalSplitterWidth - groupMarksReserve();
  const OLD_TREE_WIDTH = 160;
  const hideLabelsEl = document.getElementById('hideLabels');
  const hideLabels = hideLabelsEl && hideLabelsEl.checked;
  const OLD_LABEL_WIDTH = hideLabels ? 0 : 80;
  const OLD_MARGIN_LEFT = 40;
  
    const firstPanelWidth = OLD_MARGIN_LEFT + OLD_TREE_WIDTH;
    const secondPanelWidth = OLD_LABEL_WIDTH + (hideLabels ? 0 : 6);
  
  // Calculate heatmap and dataframe panel counts
  const heatmapPanels = Array.from(document.querySelectorAll('.heatmap-panel'));
  const dataframePanels = Array.from(document.querySelectorAll('.dataframe-panel'));
  const heatmapPanelCount = heatmapPanels.length;
  const dataframePanelCount = dataframePanels.length;
  
  // Calculate remaining width after tree and labels panels
    const remainingWidth = availableWidth - firstPanelWidth - secondPanelWidth;
  
  // Allocate fixed width for heatmap panels (20-40px each)
  const heatmapPanelWidth = Math.min(MAX_HEATMAP_PANEL_WIDTH, Math.max(MIN_HEATMAP_PANEL_WIDTH, Math.floor(remainingWidth * 0.1)));
  const totalHeatmapWidth = heatmapPanelCount * heatmapPanelWidth;
  const remainingForDataframes = remainingWidth - totalHeatmapWidth;
  
  panelWidths = [firstPanelWidth, secondPanelWidth];
  
  // Add heatmap panel widths
  for (let i = 0; i < heatmapPanelCount; i++) {
    panelWidths.push(heatmapPanelWidth);
  }
  
  // Add dataframe panel widths
  if (dataframePanelCount > 0) {
    const widthPerDataframePanel = Math.floor(remainingForDataframes / dataframePanelCount);
    const extraWidth = remainingForDataframes % dataframePanelCount;
    
    for (let i = 0; i < dataframePanelCount; i++) {
      let panelWidth = widthPerDataframePanel;
      if (i < extraWidth) {
        panelWidth += 1;
      }
      panelWidths.push(panelWidth);
    }
  } else if (heatmapPanelCount > 0) {
    // If no dataframes but we have heatmaps, add a placeholder panel width
    panelWidths.push(Math.max(MIN_DATAFRAME_PANEL_WIDTH, remainingForDataframes));
  }
  
  for (let i = 0; i < panelWidths.length; i++) {
    const minWidth = getMinPanelWidth(i);
    if (panelWidths[i] < minWidth) {
      panelWidths[i] = minWidth;
    }
  }
  
  normalizeWidths();
  initializePanels();
  updatePanelHeights();
  
  if (panelCount >= 4) {
    const treePanelWidth = panelWidths[0];
    const labelsPanelWidth = panelWidths[1];
    const gapBetweenPanels = 8;
    
    const metadataStartX = treePanelWidth + labelsPanelWidth + 8;
    
    // Calculate metadata panel boundaries considering heatmap panels
    const heatmapWidth = heatmapPanelCount * heatmapPanelWidth;
    const dataframeStartX = metadataStartX + heatmapWidth;
    
    if (dataframePanelCount >= 2) {
      const firstDataframeWidth = panelWidths[2 + heatmapPanelCount];
      const secondDataframeWidth = panelWidths[3 + heatmapPanelCount];
      
      window.metadataPanelBoundaries = {
        leftPanelEnd: dataframeStartX + firstDataframeWidth,
        rightPanelStart: dataframeStartX + firstDataframeWidth + gapBetweenPanels,
        leftPanelWidth: firstDataframeWidth,
        rightPanelWidth: secondDataframeWidth,
        splitterX: dataframeStartX + firstDataframeWidth
      };
    }
  }
  
  setTimeout(() => {
    if (typeof drawTree === 'function') {
      drawTree();
      updateZoomBounds();
    }
  }, 0);
}

function getHeatmapPanelDimensions(heatmapIndex = 0) {
  const positions = getPanelPositions();
  const heatmapPanels = positions.filter(p => p.type.startsWith('heatmap'));
  
  if (heatmapIndex < heatmapPanels.length) {
    return heatmapPanels[heatmapIndex];
  }
  return null;
}

function updateHeatmapMasterCheckbox(heatmapId) {
  const masterCheckbox = document.getElementById(`heatmapToggle${heatmapId}`);
  const heatmapDiv = document.getElementById(`heatmapData${heatmapId}`);
  
  if (!masterCheckbox || !heatmapDiv) return;
  
  const individualCheckboxes = heatmapDiv.querySelectorAll('.heatmap-value-toggle');
  if (individualCheckboxes.length === 0) return;
  
  const checkedCount = Array.from(individualCheckboxes).filter(cb => cb.checked).length;
  const totalCount = individualCheckboxes.length;
  
  // Update master checkbox state
  if (checkedCount === 0) {
    // All unchecked - master should be unchecked
    masterCheckbox.checked = false;
    masterCheckbox.indeterminate = false;
  } else if (checkedCount === totalCount) {
    // All checked - master should be checked
    masterCheckbox.checked = true;
    masterCheckbox.indeterminate = false;
  } else {
    // Some checked - master should be indeterminate
    masterCheckbox.checked = false;
    masterCheckbox.indeterminate = true;
  }
}

