function createNewHighlightCard(highlightData) {
  // Get existing highlight IDs to determine next ID
  const existingIds = Array.from(document.querySelectorAll('.highlight-panel'))
    .map(n => {
      const m = (n.id || '').match(/highlightCard(\d+)/);
      return m ? parseInt(m[1], 10) : NaN;
    })
    .filter(Number.isFinite);
  
  const nextId = existingIds.length ? Math.max(...existingIds) + 1 : 1;
  const highlightId = nextId;
  
  const cardId = `highlightCard${highlightId}`;
  
  // Create the new highlight card HTML
  const newCard = document.createElement('details');
  newCard.id = cardId;
  newCard.className = 'highlight-panel';
  newCard.setAttribute('data-hlid', String(highlightId));
  
  // Close ALL open tabs in the sidebar to ensure only one tab is expanded at a time
  const allOpenTabs = document.querySelectorAll('aside details[open]');
  allOpenTabs.forEach(tab => {
    tab.removeAttribute('open');
  });
  
  // Now open the new card
  newCard.setAttribute('open', '');
  
  newCard.innerHTML = `
    <summary id="highlightSummary${highlightId}" class="df-summary">
      <span class="pro-card-badge pro-badge-highlight" aria-hidden="true">HL</span>
      <span id="highlightTitle${highlightId}" class="pro-card-title">Highlight</span>
      <span class="df-spacer"></span>
      <button id="deleteHighlight${highlightId}" class="df-delete" title="Remove highlight" aria-label="Remove highlight"></button>
      <span class="drag-handle disabled" title="Drag disabled for highlights" aria-hidden="true"></span>
    </summary>
    <div class="section row2 pro-card-body">
      <div class="pro-card-section">
        <label class="pro-row"><span>Show highlight</span><input type="checkbox" id="highlightToggle${highlightId}" class="highlight-toggle pro-switch" checked></label>
        <div class="pro-range-row">
          <label for="highlightTransparency${highlightId}">Opacity</label>
          <input type="range" id="highlightTransparency${highlightId}" class="highlight-transparency" min="10" max="100" value="25" step="5">
          <span class="pro-num-wrap"><input type="number" id="highlightTransparencyValue${highlightId}" class="pro-num pro-num-sm" min="10" max="100" value="25" step="5" aria-label="Opacity (%)"><span class="pro-unit">%</span></span>
        </div>
        <div class="pro-card-head"><span class="pro-section-title">Categories</span></div>
        <div id="highlightData${highlightId}" class="pro-list"><i>Highlight data loaded</i></div>
      </div>
    </div>
  `;
  
  // Insert the new card in the highlight container
  const highlightContainer = document.getElementById('highlightContainer');
  if (!highlightContainer) {
    return null;
  }
  
  // Simply append to the highlight container
  highlightContainer.appendChild(newCard);
  
  // Update section visibility
  updateSectionVisibilities();
  
  // Add event listener for delete button
  const deleteBtn = newCard.querySelector(`#deleteHighlight${highlightId}`);
  deleteBtn.addEventListener('click', (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    deleteHighlightCard(highlightId);
  });
  
  // Add event listeners for transparency controls
  const transparencySlider = newCard.querySelector(`#highlightTransparency${highlightId}`);
  const transparencyValue = newCard.querySelector(`#highlightTransparencyValue${highlightId}`);
  
  const updateTransparency = (value) => {
    // Update transparency in highlight data
    const highlightData = highlights.get(highlightId);
    if (highlightData) {
      highlightData.transparency = parseInt(value);
      highlights.set(highlightId, highlightData);
      drawTree(); // Redraw to apply new transparency
    }
  };
  
  // Sync slider and number input
  transparencySlider.addEventListener('input', (ev) => {
    const value = ev.target.value;
    transparencyValue.value = value;
    updateTransparency(value);
  });
  
  transparencyValue.addEventListener('input', (ev) => {
    const value = ev.target.value;
    transparencySlider.value = value;
    updateTransparency(value);
  });
  
  // Store highlight data using a separate Map
  if (!highlights) {
    highlights = new Map();
  }
  highlights.set(highlightId, {
    id: highlightId,
    data: highlightData,
    visible: true,
    type: 'highlight',
    transparency: 25 // Default transparency value
  });
  
  return highlightId;
}

async function handleHighlightFile(f){
  try{
    const txt = await readFileAsText(f);
    
    // Validate highlight format before parsing
    const validation = validateHighlightFormat(txt);
    if (!validation.valid) {
      const userConfirmed = confirm(`Highlight format validation failed!\n\n${validation.error}\n\nThis might be the wrong format. Would you like to proceed anyway?`);
      if (!userConfirmed) {
        setStatus('Highlight loading cancelled by user');
        return;
      }
      // User chose to continue despite validation failure
      setStatus('Proceeding with highlight loading despite format issues...');
    }
    
    const parsedHighlightData = parseTable(txt);
    
    // Check if there's already an active highlight card
    const existingHighlightCards = document.querySelectorAll('.highlight-panel');
    if (existingHighlightCards.length > 0) {
      const userConfirmed = confirm(`A highlight data already exists.\n\nProceeding will remove the current highlight data.\n\nWould you like to proceed?`);
      if (!userConfirmed) {
        setStatus('Highlight loading cancelled by user');
        return;
      }
      
      // User chose to proceed - delete all existing highlight cards
      existingHighlightCards.forEach(card => {
        const highlightId = card.getAttribute('data-hlid');
        if (highlightId) {
          deleteHighlightCard(parseInt(highlightId, 10));
        }
      });
    }
    
    // Check if any accessions match between tree and highlight data
    let hasMatchingAccessions = false;
    if(root && parsedHighlightData && parsedHighlightData.byId && parsedHighlightData.byId.size > 0) {
      const leaves = root.leaves();
      for(const leaf of leaves) {
        const key = normalizeAccession(leaf.data.name);
        if(parsedHighlightData.byId.has(key)) {
          hasMatchingAccessions = true;
          break;
        }
      }
    }
    
    // Create highlight card
    const newCardId = createNewHighlightCard(parsedHighlightData);
    
    if (newCardId) {
      // Store the matching status in the highlight data
      const hl = highlights.get(newCardId);
      if (hl) {
        hl.hasMatchingData = hasMatchingAccessions;
      }
      
      // Populate the highlight card
      populateHighlightCard(newCardId, parsedHighlightData);
      setStatus(`Highlight loaded: ${f.name}`);
      
      // Add highlight panel to canvas
      addHighlight();
      
      // Update legend to show highlight legend
      updateMetadataLegend();
      
      // Redraw tree after legend update to ensure panel positions are correct
      if (root) {
        drawTree();
      }
    }
    
  }catch(e){ setStatus('Highlight parse error: '+e.message); console.error(e); }
}

function populateHighlightCard(highlightId, metadata) {
  // Store the highlight data
  if (!highlights) {
    highlights = new Map();
  }
  
  let hl = highlights.get(highlightId);
  if (!hl) {
    // Create new highlight entry if it doesn't exist
    hl = {
      id: highlightId,
      data: metadata,
      visible: true,
      type: 'highlight',
      transparency: 25 // Default transparency value
    };
    highlights.set(highlightId, hl);
  } else {
    hl.data = metadata;
    hl.type = 'highlight';
    // Preserve existing transparency if it exists
    if (!hl.transparency) {
      hl.transparency = 25;
    }
  }
  
  // Extract unique values from the second column (value column)
  const uniqueValues = new Set();
  const accessionToValue = new Map();
  
  if (metadata.rows && metadata.rows.length > 0) {
    metadata.rows.forEach((row, index) => {
      // row is an object, not an array
      const columns = metadata.columns || [];
      if (columns.length >= 2) {
        const accession = row[columns[0]]; // First column: molecule/accession
        const value = String(row[columns[1]]); // Second column: value (character or number)
        
        if (accession && value) {
          uniqueValues.add(value);
          accessionToValue.set(accession, value);
        }
      }
    });
  }
  
  // Initialize highlight data structure if not exists
  if (!hl) {
    highlights.set(highlightId, {
      id: highlightId,
      data: metadata,
      visible: true,
      type: 'highlight',
      uniqueValues: Array.from(uniqueValues).sort(naturalCompare),
      accessionToValue: accessionToValue,
      valueVisibility: new Map(),
      valueColors: new Map()
    });
  } else {
    hl.uniqueValues = Array.from(uniqueValues).sort(naturalCompare);
    hl.accessionToValue = accessionToValue;
    if (!hl.valueVisibility) hl.valueVisibility = new Map();
    if (!hl.valueColors) hl.valueColors = new Map();
  }
  
  // Assign colors to unique values using intelligent color assignment
  const sortedValues = Array.from(uniqueValues).sort(naturalCompare);
  const assignedColors = assignColors(sortedValues, 'highlight', highlightId);
  sortedValues.forEach((value, index) => {
    if (!hl.valueVisibility.has(value)) {
      hl.valueVisibility.set(value, true); // Default to visible
    }
    if (!hl.valueColors.has(value)) {
      hl.valueColors.set(value, assignedColors.get(value));
    }
  });
  
  // Populate the highlight data display with value list
  const highlightDiv = document.getElementById(`highlightData${highlightId}`);
  
  if (highlightDiv) {
    // Check if this highlight has matching accessions - if not, show warning message
    if (hl.hasMatchingData === false) {
      // Show no matching accessions message
      highlightDiv.innerHTML = `
        <div style="text-align: center; padding: 20px; color: var(--muted);">
          <div style="font-weight: bold; color: var(--destructive); margin-bottom: 8px;">
            ⚠️ No matching accessions found
          </div>
          <div style="font-size: 11px;">
            Highlight doesn't match current tree
          </div>
        </div>
      `;
    } else if (sortedValues.length > 0) {
      highlightDiv.innerHTML = `
        ${sortedValues.map(value => {
          const checked = hl.valueVisibility.get(value) ? 'checked' : '';
          const color = hl.valueColors.get(value) || '#ccc';
          return `<div class="highlight-value-card pro-list-row" data-value="${value}">
                    <input type="checkbox" class="highlight-value-toggle pro-check" data-value="${value}" ${checked} aria-label="Show ${value}">
                    <span class="highlight-value-name pro-list-name" title="${value}">${value}</span>
                    <input type="color" class="highlight-value-color pro-swatch" data-value="${value}" value="${color}" title="Colour" aria-label="Colour of ${value}">
                  </div>`;
        }).join('')}
      `;
    } else {
      highlightDiv.innerHTML = '<i>No highlight data available</i>';
    }
    
    // Add event listeners for checkboxes
    highlightDiv.querySelectorAll('.highlight-value-toggle').forEach(checkbox => {
      checkbox.addEventListener('change', ev => {
        const value = ev.target.getAttribute('data-value');
        hl.valueVisibility.set(value, ev.target.checked);
        updateHighlightMasterCheckbox(highlightId);
        updateMetadataLegend(); // Update legend to reflect visibility changes
        drawTree(); // Redraw to reflect visibility changes
      });
    });
    
    // Add event listeners for color pickers
    highlightDiv.querySelectorAll('.highlight-value-color').forEach(colorPicker => {
      colorPicker.addEventListener('change', ev => {
        const value = ev.target.getAttribute('data-value');
        hl.valueColors.set(value, ev.target.value);
        updateMetadataLegend(); // Update legend to reflect color changes
        drawTree(); // Redraw to reflect color changes
      });
    });
    
    // Add event listener for master checkbox
    const masterCheckbox = document.getElementById(`highlightToggle${highlightId}`);
    if (masterCheckbox) {
      masterCheckbox.addEventListener('change', ev => {
        const isChecked = ev.target.checked;
        hl.valueVisibility.forEach((visibility, value) => {
          hl.valueVisibility.set(value, isChecked);
        });
        
        // Update all individual checkboxes
        highlightDiv.querySelectorAll('.highlight-value-toggle').forEach(checkbox => {
          checkbox.checked = isChecked;
        });
        
        updateMetadataLegend(); // Update legend to reflect visibility changes
        drawTree(); // Redraw to reflect visibility changes
      });
    }
    
    // Initial call to update master checkbox state
    updateHighlightMasterCheckbox(highlightId);
  }
}

function deleteHighlightCard(highlightId) {
  // Hide the subcard if it's open
  const addDataframeSubcard = document.getElementById('addDataframeSubcard');
  const addDataframeBtn = document.getElementById('addDataframe');
  if (addDataframeSubcard && addDataframeBtn) {
    addDataframeSubcard.style.display = 'none';
    addDataframeBtn.classList.remove('active');
  }
  
  const highlightPanels = Array.from(document.querySelectorAll('.highlight-panel'));
  const panelIndex = highlightPanels.findIndex(panel => {
    const hl = panel.getAttribute('data-hlid');
    if (hl && /^\d+$/.test(hl)) return parseInt(hl, 10) === highlightId;
    const m = (panel.id || '').match(/highlightCard(\d+)/);
    return m && parseInt(m[1], 10) === highlightId;
  });
  
  if (panelIndex >= 0) {
    const panel = highlightPanels[panelIndex];
    panel.remove();
    
    // Remove from highlights Map
    if (highlights) {
      highlights.delete(highlightId);
    }
    
    // Reindex remaining highlight panels
    const remainingPanels = Array.from(document.querySelectorAll('.highlight-panel'));
    remainingPanels.forEach((panel, index) => {
      const newId = index + 1;
      const oldId = panel.getAttribute('data-hlid') || 
                   (panel.id.match(/highlightCard(\d+)/) && parseInt(panel.id.match(/highlightCard(\d+)/)[1], 10));
      
      if (oldId && newId !== oldId) {
        // Update panel attributes
        panel.setAttribute('data-hlid', newId);
        panel.id = `highlightCard${newId}`;
        
        // Update all child elements
        const elementsToUpdate = [
          `highlightSummary${oldId}`, `highlightTitle${oldId}`, `deleteHighlight${oldId}`,
          `highlightToggle${oldId}`, `highlightData${oldId}`
        ];
        
        elementsToUpdate.forEach(oldElementId => {
          const element = document.getElementById(oldElementId);
          if (element) {
            const newElementId = oldElementId.replace(oldId, newId);
            element.id = newElementId;
            
            // Update title text content
            if (oldElementId === `highlightTitle${oldId}`) {
              element.textContent = `Highlight ${newId}`;
            }
            
            if (oldElementId === `deleteHighlight${oldId}`) {
              // Remove all existing event listeners by cloning the element
              const newElement = element.cloneNode(true);
              element.parentNode.replaceChild(newElement, element);
              
              // Add the new event listener with the correct ID
              newElement.addEventListener('click', (ev) => {
                ev.preventDefault();
                ev.stopPropagation();
                deleteHighlightCard(newId);
              });
            }
          }
        });
      }
    });
    
    // Reindex the highlights Map
    if (highlights && highlights.size > 0) {
      const newHighlights = new Map();
      let newIndex = 1;
      highlights.forEach((value, key) => {
        if (key !== highlightId) {
          newHighlights.set(newIndex, value);
          newIndex++;
        }
      });
      highlights.clear();
      for (const [id, highlight] of newHighlights) {
        highlights.set(id, highlight);
      }
    }
    
    // Update panel system to reflect highlight deletion
    updatePanelSystemAfterDeletion();
    
    // Update legend to hide highlight legend if no highlights remain
    updateMetadataLegend();
    
    // Update section visibility
    updateSectionVisibilities();
    
    // Redraw tree
    drawTree();
  }
}

function addHighlight() {
  // The highlight functionality is now handled in the drawTree function
  // where labels get background highlighting based on highlight data
  drawTree();
}

function updateHighlightMasterCheckbox(highlightId) {
  const masterCheckbox = document.getElementById(`highlightToggle${highlightId}`);
  const highlightDiv = document.getElementById(`highlightData${highlightId}`);
  
  if (!masterCheckbox || !highlightDiv) return;
  
  const individualCheckboxes = highlightDiv.querySelectorAll('.highlight-value-toggle');
  if (individualCheckboxes.length === 0) return;
  
  const checkedCount = Array.from(individualCheckboxes).filter(cb => cb.checked).length;
  const totalCount = individualCheckboxes.length;
  
  // Update master checkbox state
  if (checkedCount === 0) {
    // All unchecked - master should be unchecked
    masterCheckbox.checked = false;
    masterCheckbox.indeterminate = false;
  } else if (checkedCount === totalCount) {
    // All checked - master should be checked
    masterCheckbox.checked = true;
    masterCheckbox.indeterminate = false;
  } else {
    // Some checked - master should be indeterminate
    masterCheckbox.checked = false;
    masterCheckbox.indeterminate = true;
  }
}

