function createNewCladeCard(cladeData) {
  // Get existing clade IDs to determine next ID
  const existingIds = Array.from(document.querySelectorAll('.clade-panel'))
    .map(n => {
      const m = (n.id || '').match(/cladeCard(\d+)/);
      return m ? parseInt(m[1], 10) : NaN;
    })
    .filter(Number.isFinite);
  
  const nextId = existingIds.length ? Math.max(...existingIds) + 1 : 1;
  const cladeId = nextId;
  
  const cardId = `cladeCard${cladeId}`;
  
  // Create the new clade card HTML
  const newCard = document.createElement('details');
  newCard.id = cardId;
  newCard.className = 'clade-panel';
  newCard.setAttribute('data-clid', String(cladeId));
  
  // Close ALL open tabs in the sidebar to ensure only one tab is expanded at a time
  const allOpenTabs = document.querySelectorAll('aside details[open]');
  allOpenTabs.forEach(tab => {
    tab.removeAttribute('open');
  });
  
  // Now open the new card
  newCard.setAttribute('open', '');
  
  newCard.innerHTML = `
    <summary id="cladeSummary${cladeId}" class="df-summary">
      <span class="pro-card-badge pro-badge-clade" aria-hidden="true">CL</span>
      <span id="cladeTitle${cladeId}" class="pro-card-title">Clade</span>
      <span class="df-spacer"></span>
      <button id="deleteClade${cladeId}" class="df-delete" title="Remove clade" aria-label="Remove clade"></button>
      <span class="drag-handle disabled" title="Drag disabled for clades" aria-hidden="true"></span>
    </summary>
    <div class="section row2 pro-card-body">
      <div class="pro-card-section">
        <label class="pro-row"><span>Show clade colours</span><input type="checkbox" id="cladeToggle${cladeId}" class="clade-toggle pro-switch" checked></label>
        <div class="pro-card-head"><span class="pro-section-title">Groups</span></div>
        <div id="cladeData${cladeId}" class="pro-list"><i>Clade data loaded</i></div>
      </div>
    </div>
  `;
  
  // Insert the new card in the proper clade group position
  const sidebar = document.querySelector('aside');
  const addDataframeContainer = document.getElementById('addDataframeContainer');
  if (!addDataframeContainer || !sidebar) {
    return null;
  }
  
  // No longer needed - clades go to cladeContainer
  
  // Insert the new card in the clade container
  const cladeContainer = document.getElementById('cladeContainer');
  if (!cladeContainer) {
    return null;
  }
  
  // Simply append to the clade container
  cladeContainer.appendChild(newCard);
  
  // Update section visibility
  updateSectionVisibilities();
  
  // Add event listener for delete button
  const deleteBtn = newCard.querySelector(`#deleteClade${cladeId}`);
  deleteBtn.addEventListener('click', (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    deleteCladeCard(cladeId);
  });
  
  // Store clade data using a separate Map
  if (!clades) {
    clades = new Map();
  }
  clades.set(cladeId, {
    id: cladeId,
    data: cladeData,
    visible: true,
    type: 'clade'
  });
  
  return cladeId;
}

async function handleCladeFile(f){
  try{
    const txt = await readFileAsText(f);
    
    // Convert alternative format to default format if needed
    const convertedTxt = convertCladeFormatToDefault(txt);
    const wasConverted = convertedTxt !== txt;
    
    if (wasConverted) {
      setStatus('Clade file detected as alternative format - converting to default format...');
    }
    
    // Validate clade format before parsing
    const validation = validateCladeFormat(convertedTxt);
    if (!validation.valid) {
      const userConfirmed = confirm(`Clade format validation failed!\n\n${validation.error}\n\nThis might be the wrong format. Would you like to proceed anyway?`);
      if (!userConfirmed) {
        setStatus('Clade loading cancelled by user');
        return;
      }
      // User chose to continue despite validation failure
      setStatus('Proceeding with clade loading despite format issues...');
    }
    
    const parsedCladeData = parseTable(convertedTxt);
    
    // Check if there's already an active clade card
    const existingCladeCards = document.querySelectorAll('.clade-panel');
    if (existingCladeCards.length > 0) {
      const userConfirmed = confirm(`A clade data already exists.\n\nProceeding will remove the current clade data.\n\nWould you like to proceed?`);
      if (!userConfirmed) {
        setStatus('Clade loading cancelled by user');
        return;
      }
      
      // User chose to proceed - delete all existing clade cards
      existingCladeCards.forEach(card => {
        const cladeId = card.getAttribute('data-clid');
        if (cladeId) {
          deleteCladeCard(parseInt(cladeId, 10));
        }
      });
    }
    
    // Check if any accessions match between tree and clade data
    let hasMatchingAccessions = false;
    if(root && parsedCladeData && parsedCladeData.byId && parsedCladeData.byId.size > 0) {
      const leaves = root.leaves();
      for(const leaf of leaves) {
        const key = normalizeAccession(leaf.data.name);
        if(parsedCladeData.byId.has(key)) {
          hasMatchingAccessions = true;
          break;
        }
      }
    }
    
    // Create clade card
    const newCardId = createNewCladeCard(parsedCladeData);
    
    if (newCardId) {
      // Store the matching status in the clade data
      const cl = clades.get(newCardId);
      if (cl) {
        cl.hasMatchingData = hasMatchingAccessions;
      }
      
      // Populate the clade card
      populateCladeCard(newCardId, parsedCladeData);
      setStatus(`Clade loaded: ${f.name}${wasConverted ? ' (converted from alternative format)' : ''}`);
      
      // Add clade panel to canvas
      addClade();
      
      // Update legend to show clade legend
      updateMetadataLegend();
      
      // Redraw tree after legend update to ensure panel positions are correct (addClade already calls drawTree, but ensure it's after legend update)
      if (root) {
        drawTree();
      }
    }
    
  }catch(e){ setStatus('Clade parse error: '+e.message); console.error(e); }
}

function convertCladeFormatToDefault(text) {
  const lines = text.replace(/\r/g,'').split(/\n/).filter(l=>l.trim().length && !l.trim().startsWith('#'));
  
  if (lines.length < 2) {
    return text; // Not enough data to determine format
  }
  
  // Check if this is the alternative format
  // Alternative format: first line has multiple columns (values), subsequent lines have accessions
  const firstLine = lines[0].split('\t');
  const secondLine = lines[1].split('\t');
  
  // If first line has multiple columns and second line has accessions (not values), it's alternative format
  if (firstLine.length > 2 && secondLine.length > 0) {
    // Check if second line contains accessions (not values) by looking for common accession patterns
    const hasAccessionPattern = secondLine.some(cell => 
      cell.match(/^[A-Z]{2,4}_?\d+/) || // Common accession patterns like NC_123456, AB123456, etc.
      cell.match(/^\d+$/) || // Pure numbers
      cell.match(/^[A-Za-z0-9_\-\.]+$/) // Alphanumeric with common separators
    );
    
    if (hasAccessionPattern) {
      // Convert alternative format to default format
      const valueColumns = firstLine; // First line contains the value names
      const convertedLines = ['molecule\tvalue']; // Header for default format
      
      // Process each data line (skip first line which is header)
      for (let i = 1; i < lines.length; i++) {
        const dataLine = lines[i].split('\t');
        
        // For each accession in this line, create a row with the corresponding value
        dataLine.forEach((accession, columnIndex) => {
          if (accession.trim() && columnIndex < valueColumns.length) {
            const value = valueColumns[columnIndex].trim();
            convertedLines.push(`${accession.trim()}\t${value}`);
          }
        });
      }
      
      return convertedLines.join('\n');
    }
  }
  
  // If not alternative format, return original text
  return text;
}

function populateCladeCard(cladeId, metadata) {
  // Store the clade data
  if (!clades) {
    clades = new Map();
  }
  
  let cl = clades.get(cladeId);
  if (!cl) {
    // Create new clade entry if it doesn't exist
    cl = {
      id: cladeId,
      data: metadata,
      visible: true,
      type: 'clade'
    };
    clades.set(cladeId, cl);
  } else {
    cl.data = metadata;
    cl.type = 'clade';
  }
  
  // Extract unique values from the second column (value column)
  const uniqueValues = new Set();
  const accessionToValue = new Map();
  
  if (metadata.rows && metadata.rows.length > 0) {
    metadata.rows.forEach((row, index) => {
      // row is an object, not an array
      const columns = metadata.columns || [];
      if (columns.length >= 2) {
        const accession = row[columns[0]]; // First column: molecule/accession
        const value = String(row[columns[1]]); // Second column: value (character or number)
        
        if (accession && value) {
          uniqueValues.add(value);
          accessionToValue.set(accession, value);
        }
      }
    });
  }
  
  // Initialize clade data structure if not exists
  if (!cl) {
    clades.set(cladeId, {
      id: cladeId,
      data: metadata,
      visible: true,
      type: 'clade',
      uniqueValues: Array.from(uniqueValues).sort(naturalCompare),
      accessionToValue: accessionToValue,
      valueVisibility: new Map(),
      valueColors: new Map()
    });
  } else {
    cl.uniqueValues = Array.from(uniqueValues).sort(naturalCompare);
    cl.accessionToValue = accessionToValue;
    if (!cl.valueVisibility) cl.valueVisibility = new Map();
    if (!cl.valueColors) cl.valueColors = new Map();
  }
  
  // Assign colors to unique values using intelligent color assignment
  const sortedValues = Array.from(uniqueValues).sort(naturalCompare);
  const assignedColors = assignColors(sortedValues, 'clade', cladeId);
  sortedValues.forEach((value, index) => {
    if (!cl.valueVisibility.has(value)) {
      cl.valueVisibility.set(value, true); // Default to visible
    }
    if (!cl.valueColors.has(value)) {
      cl.valueColors.set(value, assignedColors.get(value));
    }
  });
  
  // Populate the clade data display with value list
  const cladeDiv = document.getElementById(`cladeData${cladeId}`);
  
  if (cladeDiv) {
    // Check if this clade has matching accessions - if not, show warning message
    if (cl.hasMatchingData === false) {
      // Show no matching accessions message
      cladeDiv.innerHTML = `
        <div style="text-align: center; padding: 20px; color: var(--muted);">
          <div style="font-weight: bold; color: var(--destructive); margin-bottom: 8px;">
            ⚠️ No matching accessions found
          </div>
          <div style="font-size: 11px;">
            Clade doesn't match current tree
          </div>
        </div>
      `;
    } else if (sortedValues.length > 0) {
      cladeDiv.innerHTML = `
        ${sortedValues.map(value => {
          const checked = cl.valueVisibility.get(value) ? 'checked' : '';
          const color = cl.valueColors.get(value) || '#ccc';
          return `<div class="clade-value-card pro-list-row" data-value="${value}">
                    <input type="checkbox" class="clade-value-toggle pro-check" data-value="${value}" ${checked} aria-label="Show ${value}">
                    <span class="clade-value-name pro-list-name" title="${value}">${value}</span>
                    <input type="color" class="clade-value-color pro-swatch" data-value="${value}" value="${color}" title="Colour" aria-label="Colour of ${value}">
                  </div>`;
        }).join('')}
      `;
    } else {
      cladeDiv.innerHTML = '<i>No clade data available</i>';
    }
    
    // Add event listeners for checkboxes
    cladeDiv.querySelectorAll('.clade-value-toggle').forEach(checkbox => {
      checkbox.addEventListener('change', ev => {
        const value = ev.target.getAttribute('data-value');
        cl.valueVisibility.set(value, ev.target.checked);
        updateCladeMasterCheckbox(cladeId);
        updateMetadataLegend(); // Update legend to reflect visibility changes
        applyCladeColorsToTree(); // Apply clade colors to tree branches
        drawTree(); // Redraw to reflect visibility changes
      });
    });
    
    // Add event listeners for color pickers
    cladeDiv.querySelectorAll('.clade-value-color').forEach(colorPicker => {
      colorPicker.addEventListener('change', ev => {
        const value = ev.target.getAttribute('data-value');
        cl.valueColors.set(value, ev.target.value);
        updateMetadataLegend(); // Update legend to reflect color changes
        applyCladeColorsToTree(); // Apply clade colors to tree branches
        drawTree(); // Redraw to reflect color changes
      });
    });
    
    // Add event listener for master checkbox
    const masterCheckbox = document.getElementById(`cladeToggle${cladeId}`);
    if (masterCheckbox) {
      masterCheckbox.addEventListener('change', ev => {
        const isChecked = ev.target.checked;
        cl.valueVisibility.forEach((visibility, value) => {
          cl.valueVisibility.set(value, isChecked);
        });
        
        // Update all individual checkboxes
        cladeDiv.querySelectorAll('.clade-value-toggle').forEach(checkbox => {
          checkbox.checked = isChecked;
        });
        
        updateMetadataLegend(); // Update legend to reflect visibility changes
        applyCladeColorsToTree(); // Apply clade colors to tree branches
        drawTree(); // Redraw to reflect visibility changes
      });
    }
    
    // Initial call to update master checkbox state
    updateCladeMasterCheckbox(cladeId);
  }
}

function deleteCladeCard(cladeId) {
  // Show confirmation alert before deleting
  const userConfirmed = confirm(`Deleting this clade card will remove any colored branches from the tree.\n\nDo you want to proceed?`);
  if (!userConfirmed) {
    setStatus('Clade deletion cancelled by user');
    return;
  }
  
  // Hide the subcard if it's open
  const addDataframeSubcard = document.getElementById('addDataframeSubcard');
  const addDataframeBtn = document.getElementById('addDataframe');
  if (addDataframeSubcard && addDataframeBtn) {
    addDataframeSubcard.style.display = 'none';
    addDataframeBtn.classList.remove('active');
  }
  
  const cladePanels = Array.from(document.querySelectorAll('.clade-panel'));
  const panelIndex = cladePanels.findIndex(panel => {
    const cl = panel.getAttribute('data-clid');
    if (cl && /^\d+$/.test(cl)) return parseInt(cl, 10) === cladeId;
    const m = (panel.id || '').match(/cladeCard(\d+)/);
    return m && parseInt(m[1], 10) === cladeId;
  });
  
  if (panelIndex >= 0) {
    const panel = cladePanels[panelIndex];
    panel.remove();
    
    // Remove from clades Map
    if (clades) {
      clades.delete(cladeId);
    }
    
    // Reindex remaining clade panels
    const remainingPanels = Array.from(document.querySelectorAll('.clade-panel'));
    remainingPanels.forEach((panel, index) => {
      const newId = index + 1;
      const oldId = panel.getAttribute('data-clid') || 
                   (panel.id.match(/cladeCard(\d+)/) && parseInt(panel.id.match(/cladeCard(\d+)/)[1], 10));
      
      if (oldId && newId !== oldId) {
        // Update panel attributes
        panel.setAttribute('data-clid', newId);
        panel.id = `cladeCard${newId}`;
        
        // Update all child elements
        const elementsToUpdate = [
          `cladeSummary${oldId}`, `cladeTitle${oldId}`, `deleteClade${oldId}`,
          `cladeToggle${oldId}`, `cladeData${oldId}`
        ];
        
        elementsToUpdate.forEach(oldElementId => {
          const element = document.getElementById(oldElementId);
          if (element) {
            const newElementId = oldElementId.replace(oldId, newId);
            element.id = newElementId;
            
            // Update title text content
            if (oldElementId === `cladeTitle${oldId}`) {
              element.textContent = `Clade ${newId}`;
            }
            
            if (oldElementId === `deleteClade${oldId}`) {
              // Remove all existing event listeners by cloning the element
              const newElement = element.cloneNode(true);
              element.parentNode.replaceChild(newElement, element);
              
              // Add the new event listener with the correct ID
              newElement.addEventListener('click', (ev) => {
                ev.preventDefault();
                ev.stopPropagation();
                deleteCladeCard(newId);
              });
            }
          }
        });
      }
    });
    
    // Reindex the clades Map
    if (clades && clades.size > 0) {
      const newClades = new Map();
      let newIndex = 1;
      clades.forEach((value, key) => {
        if (key !== cladeId) {
          newClades.set(newIndex, value);
          newIndex++;
        }
      });
      clades.clear();
      for (const [id, clade] of newClades) {
        clades.set(id, clade);
      }
    }
    
    // Update panel system to reflect clade deletion
    updatePanelSystemAfterDeletion();
    
    // Update legend to hide clade legend if no clades remain
    updateMetadataLegend();
    
    // Reset clade colors to tree branches (call reset directly since clade data is already removed)
    resetCladeColors();
    
    // Update section visibility
    updateSectionVisibilities();
    
    // Redraw tree
    drawTree();
    
    setStatus('Clade card deleted and colored branches removed from tree');
  }
}

function addClade() {
  // Reset and apply clade colors to tree branches using existing search and color path functions
  applyCladeColorsToTree();
  
  // The clade functionality is now handled in the drawTree function
  // where labels get background highlighting based on clade data
  drawTree();
}

function applyCladeColorsToTree() {
  if (!root || !clades || clades.size === 0) return;
  
  // First, reset all clade colors to ensure clean state
  resetCladeColors();
  
  // For each clade data
  clades.forEach((cladeData, cladeId) => {
    if (!cladeData.hasMatchingData || !cladeData.accessionToValue || !cladeData.valueColors) return;
    
    // Group accessions by their clade values
    const valueToAccessions = new Map();
    cladeData.accessionToValue.forEach((value, accession) => {
      if (cladeData.valueVisibility && cladeData.valueVisibility.get(value)) {
        if (!valueToAccessions.has(value)) {
          valueToAccessions.set(value, []);
        }
        valueToAccessions.get(value).push(accession);
      }
    });
    
    // For each clade value, search and apply color
    valueToAccessions.forEach((accessions, value) => {
      if (accessions.length === 0) return;
      
      const color = cladeData.valueColors.get(value);
      if (!color) return;
      
      // Step 1: Pool accessions with same clade value as comma-separated string
      const accessionString = accessions.join(',');
      
      // Step 2: Use search function to highlight these accessions
      performSearch(accessionString);
      
      // Step 3: Apply color path function to color the branches
      applyCladeColorPath(color);
    });
  });
  
  // Clear search state after applying all clade colors to prevent selection from remaining active
  clearSearch();
}

function updateCladeMasterCheckbox(cladeId) {
  const masterCheckbox = document.getElementById(`cladeToggle${cladeId}`);
  const cladeDiv = document.getElementById(`cladeData${cladeId}`);
  
  if (!masterCheckbox || !cladeDiv) return;
  
  const individualCheckboxes = cladeDiv.querySelectorAll('.clade-value-toggle');
  if (individualCheckboxes.length === 0) return;
  
  const checkedCount = Array.from(individualCheckboxes).filter(cb => cb.checked).length;
  const totalCount = individualCheckboxes.length;
  
  // Update master checkbox state
  if (checkedCount === 0) {
    // All unchecked - master should be unchecked
    masterCheckbox.checked = false;
    masterCheckbox.indeterminate = false;
  } else if (checkedCount === totalCount) {
    // All checked - master should be checked
    masterCheckbox.checked = true;
    masterCheckbox.indeterminate = false;
  } else {
    // Some checked - master should be indeterminate
    masterCheckbox.checked = false;
    masterCheckbox.indeterminate = true;
  }
}

