let _resizeTO = null;
let _suppressAutoFitUntil = 0;

function suppressAutoFit(ms){ _suppressAutoFitUntil = Date.now() + (ms||250); }

function shouldSuppressAutoFit(){ return Date.now() < _suppressAutoFitUntil; }

function autoFitOnResize(){
  if(shouldSuppressAutoFit && shouldSuppressAutoFit()) return;
  if(!root) return;
  const expPct = tipSpacingSel ? (+tipSpacingSel.value||0) : 0;
  if(geometry === 'rect'){
    if(expPct <= 0){
      drawTree();
    } else {
      drawTree();
      anchorTopLeftPreserveScale();
    }
  } else {
    drawTree();
    centerRadial();
  }
}

