function scheduleAutoFit(){
  if(_resizeTO) clearTimeout(_resizeTO);
  _resizeTO = setTimeout(()=>{ _resizeTO = null; autoFitOnResize(); }, 120);
}

(function installResizeAutoFit(){
  const svgEl = document.getElementById('svg');
  const canvasEl = document.getElementById('canvas');
  try{
    const ro = new ResizeObserver(()=> scheduleAutoFit());
    if(svgEl) ro.observe(svgEl);
    if(canvasEl) ro.observe(canvasEl);
  }catch(e){ /* older browsers */ }
  window.addEventListener('resize', scheduleAutoFit);
  
  window.addEventListener('resize', function() {
    if (!isDragging) {
      normalizeWidths();
      updatePanelPositions();
      updateSplitterPositions();
      updatePanelHeights();
      updateDisplay();
    }
  });
  
  // setupCanvasDimensionMonitoring(); //USER SILENCED THIS LINE
})();

