// UPGMA tree construction algorithm
function upgmaTree(distanceMatrix, labels) {
  const n = labels.length;
  if (n === 0) return null;
  if (n === 1) return { name: labels[0], branchLength: 0 };
  
  
  // Initialize clusters (each sequence is its own cluster initially)
  const clusters = labels.map((label, i) => ({
    name: label,
    height: 0,  // Height of this cluster (for UPGMA)
    size: 1,
    index: i
  }));
  
  // Create a copy of the distance matrix
  const dist = distanceMatrix.map(row => [...row]);
  const active = new Array(n).fill(true);
  
  let step = 0;
  while (clusters.filter((c, i) => active[i]).length > 1) {
    step++;
    
    // Find minimum distance between active clusters
    let minDist = Infinity;
    let minI = -1, minJ = -1;
    
    for (let i = 0; i < n; i++) {
      if (!active[i]) continue;
      for (let j = i + 1; j < n; j++) {
        if (!active[j]) continue;
        if (dist[i][j] < minDist) {
          minDist = dist[i][j];
          minI = i;
          minJ = j;
        }
      }
    }
    
    if (minI === -1 || minJ === -1) break;
    
    
    // Calculate new cluster height (average distance / 2)
    const newHeight = minDist / 2;
    
    // Calculate branch lengths from parent to children
    const branchLengthI = newHeight - clusters[minI].height;
    const branchLengthJ = newHeight - clusters[minJ].height;
    
    // Create new cluster by merging i and j
    const newCluster = {
      children: [
        { ...clusters[minI], branchLength: branchLengthI },
        { ...clusters[minJ], branchLength: branchLengthJ }
      ],
      height: newHeight,
      size: clusters[minI].size + clusters[minJ].size,
      index: minI
    };
    
    // Update distance matrix using UPGMA averaging
    for (let k = 0; k < n; k++) {
      if (!active[k] || k === minI || k === minJ) continue;
      
      const newDist = (dist[minI][k] * clusters[minI].size + dist[minJ][k] * clusters[minJ].size) / 
                      (clusters[minI].size + clusters[minJ].size);
      dist[minI][k] = dist[k][minI] = newDist;
    }
    
    // Mark j as inactive and replace i with new cluster
    active[minJ] = false;
    clusters[minI] = newCluster;
  }
  
  // console.log('========== UPGMA CLUSTERING COMPLETE ==========\n');
  
  // Find the remaining active cluster (root)
  const rootIndex = active.findIndex(a => a);
  return clusters[rootIndex];
}

// Neighbor-Joining (Saitou & Nei; the plain NJ of R's ape::nj, not BIONJ)
function neighborJoiningTree(distanceMatrix, labels) {
  const n = labels.length;
  if (n === 0) return null;
  if (n === 1) return { name: labels[0], branchLength: 0 };
  if (n === 2) {
    // Base case: two nodes
    const dist = distanceMatrix[0][1];
    return {
      children: [
        { name: labels[0], branchLength: dist / 2 },
        { name: labels[1], branchLength: dist / 2 }
      ]
    };
  }
  
  // console.log('\n========== NEIGHBOR-JOINING CLUSTERING PROCESS ==========');
  
  // Initialize nodes
  const nodes = labels.map((label, i) => ({
    name: label,
    index: i,
    isLeaf: true
  }));
  
  // Create a copy of the distance matrix
  const dist = distanceMatrix.map(row => [...row]);
  const active = new Array(n).fill(true);
  let nodeCounter = n;
  
  let step = 0;
  while (nodes.filter((_, i) => active[i]).length > 2) {
    step++;
    
    // Get active indices
    const activeIndices = [];
    for (let i = 0; i < nodes.length; i++) {
      if (active[i]) activeIndices.push(i);
    }
    const numActive = activeIndices.length;
    
    // Calculate divergence (sum of distances) for each active node
    const divergence = new Array(nodes.length).fill(0);
    for (const i of activeIndices) {
      for (const j of activeIndices) {
        if (i !== j) {
          divergence[i] += dist[i][j];
        }
      }
    }
    
    // Calculate Q-matrix and find minimum
    let minQ = Infinity;
    let minI = -1, minJ = -1;
    
    for (let idx = 0; idx < activeIndices.length; idx++) {
      const i = activeIndices[idx];
      for (let jdx = idx + 1; jdx < activeIndices.length; jdx++) {
        const j = activeIndices[jdx];
        const q = (numActive - 2) * dist[i][j] - divergence[i] - divergence[j];
        if (q < minQ) {
          minQ = q;
          minI = i;
          minJ = j;
        }
      }
    }
    
    if (minI === -1 || minJ === -1) break;
    
    // Get node names for logging
    const getNodeName = (node) => {
      if (node.children) {
        return `(${node.children.map(c => getNodeName(c)).join(',')})`;
      }
      return node.name || `node${node.index}`;
    };
    
    // console.log(`\nStep ${step}:`);
    // console.log(`  Active nodes: ${numActive}`);
    // console.log(`  Merging nodes at indices ${minI} and ${minJ}`);
    // console.log(`  Node ${minI}: ${getNodeName(nodes[minI])}`);
    // console.log(`  Node ${minJ}: ${getNodeName(nodes[minJ])}`);
    // console.log(`  Distance between them: ${dist[minI][minJ].toFixed(10)}`);
    // console.log(`  Q value: ${minQ.toFixed(10)}`);
    
    // Calculate branch lengths
    const dij = dist[minI][minJ];
    const branchLengthI = 0.5 * dij + (divergence[minI] - divergence[minJ]) / (2 * (numActive - 2));
    const branchLengthJ = dij - branchLengthI;
    
    // console.log(`  Branch length to node ${minI}: ${branchLengthI.toFixed(10)}`);
    // console.log(`  Branch length to node ${minJ}: ${branchLengthJ.toFixed(10)}`);
    
    // Create new internal node
    const newNode = {
      children: [
        { ...nodes[minI], branchLength: branchLengthI },
        { ...nodes[minJ], branchLength: branchLengthJ }
      ],
      index: nodeCounter++,
      isLeaf: false
    };
    
    // Calculate distances from new node to all other active nodes
    const newDistances = new Array(nodes.length);
    for (const k of activeIndices) {
      if (k === minI || k === minJ) continue;
      newDistances[k] = 0.5 * (dist[minI][k] + dist[minJ][k] - dij);
      // console.log(`    To node ${k} (${getNodeName(nodes[k])}): ${newDistances[k].toFixed(10)}`);
    }
    
    // Add new node and update distance matrix
    nodes.push(newNode);
    active.push(true);
    
    // Extend distance matrix for new node
    for (let i = 0; i < dist.length; i++) {
      dist[i].push(newDistances[i] || 0);
    }
    dist.push([...newDistances, 0]);
    
    // Mark old nodes as inactive
    active[minI] = false;
    active[minJ] = false;
  }
  
  // console.log('\n========== CLUSTERING COMPLETE ==========\n');
  
  // Find the last two active nodes and join them
  const remaining = [];
  for (let i = 0; i < nodes.length; i++) {
    if (active[i]) remaining.push(i);
  }
  
  if (remaining.length === 2) {
    const i = remaining[0];
    const j = remaining[1];
    const finalDist = dist[i][j];
    
    // console.log(`Final join: nodes ${i} and ${j}, distance: ${finalDist.toFixed(10)}`);
    
    return {
      children: [
        { ...nodes[i], branchLength: finalDist / 2 },
        { ...nodes[j], branchLength: finalDist / 2 }
      ]
    };
  }
  
  // Fallback: return the last active node
  const lastActive = remaining[0];
  return nodes[lastActive];
}

// Convert tree to Newick format
function treeToNewick(node) {
  if (!node) return '';
  
  if (node.children) {
    const childrenNewick = node.children.map(child => {
      const subtree = treeToNewick(child);
      const length = child.branchLength !== undefined ? `:${child.branchLength.toFixed(6)}` : '';
      return subtree + length;
    }).join(',');
    return `(${childrenNewick})`;
  } else {
    // Leaf node
    return node.name || '';
  }
}

// Calculate Jaccard distance matrix from gene presence/absence
function calculateJaccardDistanceMatrix(dataframe) {
  if (!dataframe || !dataframe.meta || !dataframe.meta.rows) {
    throw new Error('Invalid dataframe data');
  }
  
  const rows = dataframe.meta.rows;
  const columns = dataframe.meta.columns || [];
  
  
  if (columns.length < 2) {
    throw new Error(`Dataframe must have at least 2 columns (molecule/accession and gene). Found ${columns.length} column(s): ${columns.join(', ')}`);
  }
  
  // Use header-aware column detection instead of hardcoded positions
  const columnIndices = getDataframeColumnIndices(dataframe.meta);
  const moleculeCol = columnIndices.moleculeCol;
  const geneCol = columnIndices.geneCol;
  
  
  // Build gene sets for each molecule
  const moleculeGenes = new Map();
  
  rows.forEach((row, idx) => {
    const molecule = row[moleculeCol];
    const gene = row[geneCol];
    
    
    if (molecule && gene) {
      const moleculeTrimmed = String(molecule).trim();
      const geneTrimmed = String(gene).trim();
      
      if (!moleculeGenes.has(moleculeTrimmed)) {
        moleculeGenes.set(moleculeTrimmed, new Set());
      }
      moleculeGenes.get(moleculeTrimmed).add(geneTrimmed);
    }
  });
  
  // Get unique molecules
  const molecules = Array.from(moleculeGenes.keys()).sort();
  const n = molecules.length;
  
  if (n < 2) {
    throw new Error(`Need at least 2 molecules/accessions to generate a tree. Found ${n} molecule(s).`);
  }
  
  // Calculate Jaccard distance matrix
  const distanceMatrix = Array(n).fill(null).map(() => Array(n).fill(0));
  
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const genes_i = moleculeGenes.get(molecules[i]);
      const genes_j = moleculeGenes.get(molecules[j]);
      
      // Calculate Jaccard similarity
      const intersection = new Set([...genes_i].filter(g => genes_j.has(g)));
      const union = new Set([...genes_i, ...genes_j]);
      
      const jaccardSimilarity = intersection.size / union.size;
      const jaccardDistance = 1 - jaccardSimilarity;
      
      distanceMatrix[i][j] = jaccardDistance;
      distanceMatrix[j][i] = jaccardDistance;
    }
  }
  
  return { distanceMatrix, labels: molecules };
}

// Generate tree from gene content
async function generateTreeFromGeneContent() {
  labelsAutoHideDone = false;
  try {
    if (!selectedGeneDataFile) {
      setStatus('Error: No gene data file selected.');
      return;
    }
    
    setStatus('Reading gene data file...');
    
    // Read the gene data file
    const text = await selectedGeneDataFile.text();
    const rows = text.trim().split(/\r?\n/);
    if (rows.length < 2) {
      setStatus('Error: Gene data file must have at least a header and one data row.');
      return;
    }
    
    // Parse the file (detect delimiter: TSV or CSV)
    const firstLine = rows[0];
    const delimiter = firstLine.includes('\t') ? '\t' : ',';
    const header = firstLine.split(delimiter).map(h => h.trim());
    
    
    // Parse data rows
    const parsedRows = [];
    for (let i = 1; i < rows.length; i++) {
      const cols = rows[i].split(delimiter).map(c => c.trim());
      if (cols.length > 0 && cols[0]) { // Skip empty rows
        const rowObj = {};
        header.forEach((h, idx) => {
          rowObj[h] = cols[idx] || '';
        });
        parsedRows.push(rowObj);
        
        // Log first few rows
        if (i <= 5) {
        }
      }
    }
    
    
    // Check for unique values in first column
    const uniqueFirstCol = new Set(parsedRows.map(r => r[header[0]]));
    
    if (parsedRows.length === 0) {
      setStatus('Error: No valid data rows found in gene data file.');
      return;
    }
    
    // Create a minimal dataframe structure for the calculation
    const dataframe = {
      meta: {
        rows: parsedRows,
        columns: header
      }
    };
    
    setStatus(`Calculating Jaccard distance matrix from ${parsedRows.length} gene entries...`);
    
    // Calculate distance matrix
    const { distanceMatrix, labels } = calculateJaccardDistanceMatrix(dataframe);
    
    // Get selected algorithm
    const algorithmNJ = document.getElementById('algorithmNJ');
    const algorithmUPGMA = document.getElementById('algorithmUPGMA');
    const useNJ = algorithmNJ && algorithmNJ.checked;
    const algorithmName = useNJ ? 'Neighbor-Joining' : 'UPGMA';
    
    setStatus(`Found ${labels.length} unique molecules. Building tree using ${algorithmName}...`);
    
    // Build tree using selected algorithm
    const tree = useNJ ? neighborJoiningTree(distanceMatrix, labels) : upgmaTree(distanceMatrix, labels);
    
    if (!tree) {
      setStatus('Error: Failed to construct tree');
      return;
    }
    
    // Convert to Newick format
    const newick = treeToNewick(tree) + ';';
    
    
    // Count tips in Newick (rough estimate by counting leaf names)
    const tipMatches = newick.match(/[a-zA-Z0-9_]+:/g);
    
    setStatus('Tree generated successfully. Loading...');
    
    // Load the generated tree
    const treeBlob = new Blob([newick], { type: 'text/plain' });
    const treeFile = new File([treeBlob], 'generated_tree.newick', { type: 'text/plain' });
    
    await handleTreeFile(treeFile);
    
    currentLoadedTreeFile = 'Generated from gene content';
    
    setStatus(`Tree generated from ${labels.length} molecules using ${algorithmName} (Jaccard distance)`);
    
  } catch (error) {
    console.error('Error generating tree:', error);
    setStatus(`Error generating tree: ${error.message}`);
  }
}

