let _fitViewState = { leafSepPx: null, nLeaves: null };

function onFitToViewRect(){
  if(!root){ setStatus('Load a Newick tree'); return; }

  if(geometry !== 'rect'){
    // For radial mode, sync panel system before drawing
    if(geometry === 'radial' && window.radialPanelSystem){
      window.radialPanelSystem.sync();
    }
    drawTree();
    if(geometry === 'radial'){
      centerRadial();
    }
    // Don't use fitToView() for radial - centerRadial() handles positioning
    return;
  }

  const svgEl = document.getElementById('svg');
  const canvasW = svgEl ? svgEl.clientWidth : 0;
  const canvasH = svgEl ? svgEl.clientHeight : 0;
  const labelPx = +(document.getElementById('labelSize')?.value || 12);
  const barW    = +(document.getElementById('trackWidth')?.value || 0);
  const firstMeta = getFirstDataframeMeta();
  const hasBars = !!(firstMeta && barW > 0);
  const hasTwoLinePlaceholder = hasBars && !(metaColumn && firstMeta && firstMeta.rows && firstMeta.rows.length);
  const barH    = 8;
  const axisClear0 = calcLegendTopPad(labelPx, hasBars, hasTwoLinePlaceholder);
  const bottomClear0 = Math.ceil(labelPx * 0.6) + (hasBars ? Math.ceil(barH/2) + 6 : 6);
  // with the axes below the tree, their space is at the bottom (same as drawTree)
  const below = axesBelowWanted();
  const nTips = Math.max(1, root ? root.leaves().length : 1);
  const c0 = fitClearances(axisClear0, bottomClear0, labelPx, below, 0);
  const a0 = Math.max(20, canvasH - c0.top - c0.bottom);
  const fc = fitClearances(axisClear0, bottomClear0, labelPx, below, nTips > 1 ? a0 / (nTips - 1) : a0 / 2);
  const axisClear = fc.top, bottomClear = fc.bottom;
  const availableH = Math.max(20, canvasH - axisClear - bottomClear);
  if(tipSpacingSel){ tipSpacingSel.value = '0'; }
  if(tipSpacingNum){ tipSpacingNum.value = '0'; }
  setExpansionBadge();

  const leavesArr = root ? root.leaves() : [];
  const nL = Math.max(1, leavesArr.length);
  const leafSepPx = (nL > 1) ? (availableH / (nL - 1)) : (availableH / 2);
  _fitViewState.leafSepPx = leafSepPx;
  _fitViewState.nLeaves  = nL;

  drawTree();
  fitFillNonUniform();
  reapplyPermanentColors();
  setStatus(`Fit to view — canvas ${Math.round(canvasW)}×${Math.round(canvasH)}; tips ${nL}; spacing ${leafSepPx.toFixed(1)}px`);
}

function fitFillNonUniform(){
  if(!g.node()) return;
  let bbox = g.node().getBBox();
  const svgEl = document.getElementById('svg');
  const w = svgEl.clientWidth, h = svgEl.clientHeight;

  // Reserve headroom/footroom for legend/text (match drawTree logic) and keep a right gutter
  const labelPx = +(document.getElementById('labelSize')?.value || 10);
  const trackW  = +(document.getElementById('trackWidth')?.value || 0);
  const firstMeta = getFirstDataframeMeta();
  const hasBars = !!(firstMeta && metaColumn && trackW > 0);
  const hasTwoLinePlaceholder = hasBars && !(metaColumn && firstMeta && firstMeta.rows && firstMeta.rows.length);
  const barH    = 8;
  const eps = 0; // remove expansion padding so fit is the most-zoomed-out view
  const extraTop = 0;
  const extraBottom = 0;

  // Expand bbox with those reserves
  const bbx = bbox.x - eps;
  const bby = bbox.y - eps - extraTop;
  const bbw = Math.max(1, bbox.width  + eps*2);
  const bbh = Math.max(1, bbox.height + eps*2 + extraTop + extraBottom);

  // Fill canvas without preserving aspect
  const pad = 0;
  const kx = (w - pad*2) / bbw;
  const ky = (h - pad*2) / bbh;
  const tx = -bbx * kx + pad;
  const ty = -bby * ky + pad;

  g.attr('transform', `translate(${tx},${ty}) scale(${kx},${ky})`);
  svg.call(zoom.transform, d3.zoomIdentity);
}

