// Store the last known user-defined root node
let lastKnownUserRoot = null;
let originalRoot = null;
let wasMidpointActive = false;

// Midpoint rooting (js/tree-core.js): the root goes halfway along the longest path
// between two tips, on the branch where that point falls. It does not depend on the
// current root, so applying it again changes nothing.

function handleRootingState() {
  if(rootEnableEl && rootEnableEl.checked && rootModeEl && rootModeEl.value === 'midpoint') {
    
    rerootAtNode({ midpoint: true });
    
    wasMidpointActive = true;
  } else {
    
    // If switching from ON to OFF: restore last known user defined root
    if(wasMidpointActive && lastKnownUserRoot) {

      
      if(lastKnownUserRoot === originalRoot) {
        // Use reset root function if last known root equals original root
        resetToOriginalRoot();
      } else {
        // Use rerootAtNode function for custom user-defined root
        rerootAtNode(lastKnownUserRoot);
      }
    } else if(wasMidpointActive && !lastKnownUserRoot) {
      resetToOriginalRoot();
    }
    
    wasMidpointActive = false;
  }
}

handleRootingState();
