// Legacy global variables (kept for compatibility with existing code)
let globalDragSrc = null;
let globalPlaceholder = null;

setupCardSectionDragListener('dataframeContainer');
setupCardSectionDragListener('heatmapContainer');
setupCardSectionDragListener('highlightContainer');
setupCardSectionDragListener('cladeContainer');
setupCardSectionDragListener('chartContainer');
setupCardSectionDragListener('msaContainer');

function setupCardSectionDragListener(containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;

  container.addEventListener('dragover', ev => {
    ev.preventDefault();
    ev.stopPropagation();

    if (!globalDragSrc) {
      globalDragSrc = document.querySelector('.dragging');
    }

    if (!globalDragSrc || !globalPlaceholder) return;

    // Determine card type based on the container
    const cardType = containerId.replace('Container', '');
    
    // Check if the dragged card belongs to this container type
    const draggedCardType = globalDragSrc.classList.contains('chart-panel') ? 'chart' :
                           globalDragSrc.classList.contains('heatmap-panel') ? 'heatmap' :
                           globalDragSrc.classList.contains('dataframe-panel') ? 'dataframe' :
                           globalDragSrc.classList.contains('highlight-panel') ? 'highlight' :
                           globalDragSrc.classList.contains('clade-panel') ? 'clade' :
                           globalDragSrc.classList.contains('msa-panel') ? 'msa' : null;

    // Only allow dropping if card types match
    if (cardType !== draggedCardType) {
      return;
    }

    // Find insertion point within this container with improved sensitivity
    let after = null;
    const cards = Array.from(container.querySelectorAll(`.${cardType}-panel:not(.dragging)`));
    
    for (const card of cards) {
      const rect = card.getBoundingClientRect();
      const cardTop = rect.top;
      const cardBottom = rect.bottom;
      const cardHeight = rect.height;
      
      // Larger detection zones for better sensitivity
      const upperThreshold = cardTop + (cardHeight * 0.4); // Upper 40% threshold
      const lowerThreshold = cardTop + (cardHeight * 0.6); // Lower 60% threshold
      
      if (ev.clientY < upperThreshold) {
        // Mouse in upper 40% - insert before this card
        after = card;
        break;
      } else if (ev.clientY > lowerThreshold) {
        // Mouse in lower 40% - insert after this card
        after = card.nextSibling;
      }
      // Middle 20% zone - continue to next card for better placement
    }

    if (after) {
      container.insertBefore(globalPlaceholder, after);
    } else {
      container.appendChild(globalPlaceholder);
    }
  });
}

function updateSectionVisibilities() {
  const sections = [
    'dataframeSection', 'heatmapSection', 'highlightSection', 
    'cladeSection', 'chartSection', 'msaSection', 'textSection'
  ];
  
  // Track section visibility states
  const sectionStates = {};
  
  sections.forEach(sectionId => {
    const section = document.getElementById(sectionId);
    if (!section) return;
    
    const container = section.querySelector('.card-container');
    if (!container) return;
    
    // Check if container has any cards
    const hasCards = container.children.length > 0;
    sectionStates[sectionId] = hasCards;
    
    if (hasCards) {
      // Show section
      section.classList.remove('empty-section');
      section.style.display = '';
    } else {
      // Hide section
      section.classList.add('empty-section');
      section.style.display = 'none';
    }
  });
  
  // Check if any cards are displayed and clear global colors if none
  clearGlobalColorsIfNoCards();
}

function clearGlobalColorsIfNoCards() {
  // Check if any cards are currently displayed
  const sections = [
    'dataframeSection', 'heatmapSection', 'highlightSection', 
    'cladeSection', 'chartSection', 'msaSection', 'textSection'
  ];
  
  let hasAnyCards = false;
  
  sections.forEach(sectionId => {
    const section = document.getElementById(sectionId);
    if (!section) return;
    
    const container = section.querySelector('.card-container');
    if (!container) return;
    
    if (container.children.length > 0) {
      hasAnyCards = true;
    }
  });
  
  // If no cards are displayed, clear all global color values
  if (!hasAnyCards) {
    
    // Clear global gene colors
    if (geneColors) {
      geneColors.clear();
    }
    
    // Clear global clade colors
    if (cladeColors) {
      cladeColors.clear();
    }
    
    // Clear global clade background colors
    if (cladeBackgroundColors) {
      cladeBackgroundColors.clear();
    }
    
    // Clear all data structure Maps
    if (dataframes) {
      dataframes.clear();
    }
    
    if (heatmaps) {
      heatmaps.clear();
    }
    
    if (highlights) {
      highlights.clear();
    }
    
    if (clades) {
      clades.clear();
    }
    
    if (charts) {
      charts.clear();
    }
    
           // Clear any other global color-related variables
           if (window.pathLeafNames) {
             window.pathLeafNames.clear();
           }
           
           // Clear global color tracking
           globalUsedColors.clear();
           globalColorCounter = 0;
    
    // Clear permanent colors from tree nodes
    if (root) {
      root.descendants().forEach(node => {
        if (node.permanentColors) {
          node.permanentColors.clear();
        }
      });
    }
    
  }
}

document.addEventListener('DOMContentLoaded', () => {
  setupOneTabAtATime();
  initializePanels();
  togglePanelCanvasVisibility(false);
  
  // Update section visibilities on page load
  updateSectionVisibilities();
  
  // Show section debug mode information in console
  // console.log('  SectionDebugMode.toggle() - Show/hide section dividers and titles');
  
  setTimeout(() => {
    updateSidebarHeight();
  }, 100);
  
  const cladeColorBtn = document.getElementById('cladeColorBtn');
  const colorPickerCard = document.getElementById('colorPickerCard');
  const applyCladeColorBtn = document.getElementById('applyCladeColor');
  
  if(cladeColorBtn && colorPickerCard){
    cladeColorBtn.addEventListener('click', () => {
      const isVisible = colorPickerCard.style.display !== 'none';
      
      if (!isVisible) {
        const btnRect = cladeColorBtn.getBoundingClientRect();
        const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
        const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
        
        colorPickerCard.style.left = (btnRect.left + scrollLeft) + 'px';
        colorPickerCard.style.top = (btnRect.bottom + scrollTop + 8) + 'px';
        colorPickerCard.style.display = 'block';
      } else {
        colorPickerCard.style.display = 'none';
      }
      
      cladeColorBtn.classList.toggle('active', !isVisible);
    });
    
    document.addEventListener('click', (e) => {
      if (!colorPickerCard.contains(e.target) && !cladeColorBtn.contains(e.target)) {
        colorPickerCard.style.display = 'none';
        cladeColorBtn.classList.remove('active');
      }
    });
  }
  
  if(applyCladeColorBtn){
    applyCladeColorBtn.addEventListener('click', () => {
      if(highlightedClades.size > 0) {
        const colorPicker = document.getElementById('cladeColorPicker');
        const color = colorPicker ? colorPicker.value : '#ff6b35';
        colorActionCounter++;
        
        function colorCladeAndDescendants(node, color) {
          cladeColors.set(node, color);
          cladeColorTs.set(node, colorActionCounter);
          if (node.children) {
            node.children.forEach(child => {
              colorCladeAndDescendants(child, color);
            });
          }
        }
        
        function colorPathToRoot(node, color) {
          let current = node;
          while (current) {
            cladeColors.set(current, color);
            cladeColorTs.set(current, colorActionCounter);
            current = current.parent;
          }
        }
        
        // Apply color to all selected nodes
        highlightedClades.forEach(node => {
          colorCladeAndDescendants(node, color);
          colorPathToRoot(node, color);
          
          if(!node.permanentColors) node.permanentColors = new Map();
          node.permanentColors.set(`clade_${colorActionCounter}`, { color, ts: colorActionCounter });
        });
        
        colorPickerCard.style.display = 'none';
        cladeColorBtn.classList.remove('active');
        
        clearCladeSelection();
        
        drawTree();
      }
    });
  }
});

