// Bootstrap tab switching functionality
document.addEventListener('DOMContentLoaded', function() {
  const bootstrapTabs = document.querySelectorAll('.bootstrap-tab');
  const bootstrapTabContents = document.querySelectorAll('.bootstrap-tab-content');
  
  bootstrapTabs.forEach(tab => {
    tab.addEventListener('click', function() {
      const targetTab = this.getAttribute('data-tab');
      
      // Check the current active tab BEFORE removing the active class
      const currentActiveTab = document.querySelector('.bootstrap-tab.active')?.getAttribute('data-tab');
      
      // Remove active class from all tabs
      bootstrapTabs.forEach(t => {
        t.classList.remove('active');
        t.setAttribute('aria-selected', 'false');
      });
      
      // Add active class to clicked tab (pro UI: styled by CSS)
      this.classList.add('active');
      this.setAttribute('aria-selected', 'true');
      
      // Hide all tab contents
      bootstrapTabContents.forEach(content => {
        content.style.display = 'none';
      });
      
      // Show target tab content
      const targetContent = document.getElementById(`bootstrap-${targetTab}-tab`);
      if (targetContent) {
        targetContent.style.display = 'block';
      }
      
      // Redraw bootstrap values when switching tabs
      // For color tab, we need to redraw the entire tree to update branch colors
      // Also redraw when switching away from color tab to remove branch colors
      if (targetTab === 'color' || currentActiveTab === 'color') {
        drawTree();
      } else {
        drawBootstrapValues();
      }
      
      // Update legend when switching tabs
      updateMetadataLegend();
    });
  });
});

