function getBranchStrokeWidth() {
  const value = branchStrokeWidthEl ? +branchStrokeWidthEl.value || 1.2 : 1.2;
  return value;
}

function getDataMargin() {
  const value = dataMarginEl ? +dataMarginEl.value || 5 : 5;
  return value / 100;
}

// Bootstrap helper functions
// ---- support values
// A support value belongs to the branch above its node. Trees store them on
// different scales: proportions (0-1: FastTree SH-like, MrBayes posteriors),
// percentages (0-100: most bootstrap programs) or replicate counts (e.g. 0-1000).
// The scale is detected per tree; the range, sizes, colours and the percent text
// all work in percent of that scale, so 0.95, 95 and 950/1000 are treated alike.
function supportSourceOf() {
  return (bootstrapDataSourceEl && bootstrapDataSourceEl.value) || 'bootstrap';
}
// the support value of the branch above node d, from the chosen source (null: none)
function getSupportValue(d, source) {
  const data = d && d.data; if (!data || !d.parent) return null;   // the root has no branch
  const src = source || supportSourceOf();
  let v;
  if (src.indexOf('value:') === 0) v = data.supports ? data.supports[+src.slice(6)] : undefined;
  else if (src.indexOf('annot:') === 0) v = data.annot ? data.annot[src.slice(6)] : undefined;
  else v = data.bootstrap !== undefined ? data.bootstrap : data.bs;
  return Number.isFinite(v) ? v : null;
}
let supportScaleCache = { root: null, source: null, scale: 100, count: 0, min: null, max: null };
function getSupportScale() {
  const src = supportSourceOf();
  if (supportScaleCache.root === root && supportScaleCache.source === src) return supportScaleCache;
  // the whole tree (collapsed, cartooned and dropped parts too): the scale belongs to
  // the tree, not to what is shown
  let max = -Infinity, min = Infinity, count = 0;
  if (root) {
    const seen = new Set(), stack = [root];
    droppedNodes.forEach(d => stack.push(d));
    while (stack.length) {
      const n = stack.pop(); if (seen.has(n)) continue; seen.add(n);
      const v = getSupportValue(n, src);
      if (v !== null) { count++; if (v > max) max = v; if (v < min) min = v; }
      [n.children, n._children, n._originalChildren, n._dedupOriginalChildren].forEach(l => { if (l) l.forEach(c => stack.push(c)); });
    }
  }
  const scale = !count ? 100 : (max <= 1 ? 1 : (max <= 100 ? 100 : max));
  supportScaleCache = { root, source: src, scale, count, min: count ? min : null, max: count ? max : null };
  return supportScaleCache;
}
// support value as percent of the tree's scale (values already in percent are unchanged)
function supportPercent(v) {
  if (v === null) return null;
  const sc = getSupportScale().scale;
  return sc === 100 ? v : v * 100 / sc;
}
// numbers shown on legends, in the tree's own unit
function supportUnitLabel(pct) {
  const sc = getSupportScale().scale, v = pct / 100 * sc;
  return String(+v.toFixed(sc === 1 ? 2 : 0));
}

// Data source choices for this tree: a single support value, each value of labels
// like 95/88 (IQ-TREE SH-aLRT/UFBoot), and numeric [&...] annotations (posteriors).
function refreshSupportSources() {
  if (!bootstrapDataSourceEl) return;
  let maxParts = 0, single = false; const annot = new Map();
  if (root) {
    const all = fullTreeObject(root);
    (function walk(o, isRoot) {
      if (!isRoot) {
        if (o.supports) { maxParts = Math.max(maxParts, o.supports.length); if (o.supports.length === 1) single = true; }
        else if (Number.isFinite(o.bs)) single = true;
        if (o.annot) for (const k in o.annot) if (Number.isFinite(o.annot[k])) annot.set(k, (annot.get(k) || 0) + 1);
      }
      if (o.children) o.children.forEach(c => walk(c, false));
    })(all, true);
  }
  const opts = [];
  if (maxParts >= 2) {
    const names = maxParts === 2 ? ['1st value (e.g. SH-aLRT)', '2nd value (e.g. UFBoot)'] : null;
    for (let i = 0; i < maxParts; i++) opts.push(['value:' + i, names ? names[i] : 'Value ' + (i + 1) + ' of ' + maxParts]);
  } else if (maxParts === 1 || single) opts.push(['bootstrap', 'Support values']);
  annot.forEach((n, k) => opts.push(['annot:' + k, k + ' (annotation)']));
  if (!opts.length) opts.push(['bootstrap', 'None in this tree']);
  const prev = bootstrapDataSourceEl.value;
  bootstrapDataSourceEl.innerHTML = '';
  opts.forEach(([v, t]) => { const o = document.createElement('option'); o.value = v; o.textContent = t; bootstrapDataSourceEl.appendChild(o); });
  bootstrapDataSourceEl.value = opts.some(o => o[0] === prev) ? prev : opts[0][0];
  bootstrapDataSourceEl.disabled = opts.length < 2;
  supportScaleCache.root = null;
  updateSupportNote();
  updateMetadataLegend();   // legend numbers are in the tree's unit
}
function updateSupportNote() {
  const el = document.getElementById('bootstrapScaleNote'); if (!el) return;
  const sc = getSupportScale();
  if (!root) { el.textContent = ''; return; }
  if (!sc.count) { el.textContent = 'This tree has no support values.'; return; }
  const scaleText = sc.scale === 1 ? '0–1 (shown as 0–100%)' : (sc.scale === 100 ? '0–100' : '0–' + sc.max + ' (shown as 0–100%)');
  let text = sc.count.toLocaleString() + ' support values, scale ' + scaleText + '. Range is in percent.';
  // the file's root has two branches with different values: re-rooting keeps one of them
  const c = window.originalParsedTree ? TreeCore.rootBranchConflict(window.originalParsedTree) : null;
  if (c) text += ' The two branches at the file\'s root have different values (' + c.values.join(' and ') + '); they are one branch once the tree is re-rooted, and it keeps the lower value, ' + c.kept + '.';
  el.textContent = text;
}

// colours of support-coloured branches; cached for one redraw
let supportPaintCache = null;
function supportBranchColor(node) {
  if (!supportPaintCache) {
    const st = getBootstrapSettings();
    const tab = document.querySelector('.bootstrap-tab.active')?.getAttribute('data-tab') || 'symbol';
    supportPaintCache = { on: st.show && tab === 'color', st,
      scale: createBootstrapColorScale(st.colorMin, st.colorMax, st.colorMid, st.colorMidEnabled) };
  }
  if (!supportPaintCache.on) return null;
  const pct = supportPercent(getSupportValue(node));
  if (pct === null || pct < supportPaintCache.st.minRange || pct > supportPaintCache.st.maxRange) return null;
  return supportPaintCache.scale(pct / 100);
}

function rangeValue(el, def) {
  if (!el || el.value === '') return def;
  const v = +el.value;
  return Number.isFinite(v) ? v : def;
}
function getBootstrapSettings() {
  return {
    show: showBootstrapEl ? showBootstrapEl.checked : false,
    dataSource: bootstrapDataSourceEl ? bootstrapDataSourceEl.value || 'bootstrap' : 'bootstrap',
    // percent of the tree's support scale; an empty box means the default (0 is a real minimum)
    minRange: rangeValue(bootstrapMinRangeEl, 23),
    maxRange: rangeValue(bootstrapMaxRangeEl, 100),
    
    // Symbol tab settings
    symbolType: bootstrapSymbolTypeEl ? +bootstrapSymbolTypeEl.value || 1 : 1,
    fillColor: bootstrapFillColorEl ? bootstrapFillColorEl.value || '#ffffff' : '#ffffff',
    borderColor: bootstrapBorderColorEl ? bootstrapBorderColorEl.value || '#000000' : '#000000',
    borderWidth: bootstrapBorderWidthEl ? +bootstrapBorderWidthEl.value || 1 : 1,
    minSize: bootstrapMinSizeEl ? +bootstrapMinSizeEl.value || 5 : 5,
    maxSize: bootstrapMaxSizeEl ? +bootstrapMaxSizeEl.value || 10 : 10,
    position: bootstrapPositionEl ? (isNaN(+bootstrapPositionEl.value) ? 50 : +bootstrapPositionEl.value) : 50,
    
    // Text tab settings
    fontSize: bootstrapFontSizeEl ? +bootstrapFontSizeEl.value || 8 : 8,
    fontColor: bootstrapFontColorEl ? bootstrapFontColorEl.value || '#374151' : '#374151',
    bold: bootstrapBoldEl ? bootstrapBoldEl.getAttribute('aria-pressed') === 'true' : false,
    italic: bootstrapItalicEl ? bootstrapItalicEl.getAttribute('aria-pressed') === 'true' : false,
    textPosition: bootstrapTextPositionEl ? (isNaN(+bootstrapTextPositionEl.value) ? 50 : +bootstrapTextPositionEl.value) : 50,
    verticalShift: bootstrapVerticalShiftEl ? +bootstrapVerticalShiftEl.value || 0 : 0,
    scaleFactor: bootstrapScaleFactorEl ? +bootstrapScaleFactorEl.value || 1 : 1,
    rounding: bootstrapRoundingEl ? +bootstrapRoundingEl.value || 0 : 0,
    scientific: bootstrapScientificEl ? bootstrapScientificEl.checked : false,
    percent: bootstrapPercentEl ? bootstrapPercentEl.checked : false,
    showAll: bootstrapShowAllEl ? bootstrapShowAllEl.checked : false,
    
    // Color tab settings
    colorMin: bootstrapColorMinEl ? bootstrapColorMinEl.value || '#0000ff' : '#0000ff',
    colorMid: bootstrapColorMidEl ? bootstrapColorMidEl.value || '#ffffff' : '#ffffff',
    colorMidEnabled: bootstrapColorMidToggleEl ? !!bootstrapColorMidToggleEl.checked : false,
    colorMax: bootstrapColorMaxEl ? bootstrapColorMaxEl.value || '#8b0000' : '#8b0000'
  };
}

// Helper function to create a continuous color scale
function createBootstrapColorScale(minColor, maxColor, midColor = null, midEnabled = false) {
  // Convert hex colors to RGB
  function hexToRgb(hex) {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
      r: parseInt(result[1], 16),
      g: parseInt(result[2], 16),
      b: parseInt(result[3], 16)
    } : null;
  }
  
  // Convert RGB to hex
  function rgbToHex(r, g, b) {
    return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
  }
  
  const minRgb = hexToRgb(minColor);
  const maxRgb = hexToRgb(maxColor);
  
  if (!minRgb || !maxRgb) return () => '#000000';
  
  return function(value) {
    // Normalize value to 0-1 range
    const normalizedValue = Math.max(0, Math.min(1, value));
    
    let r, g, b;
    
    if (midEnabled && midColor) {
      const midRgb = hexToRgb(midColor);
      if (midRgb) {
        if (normalizedValue <= 0.5) {
          // Interpolate between min and mid
          const t = normalizedValue * 2;
          r = Math.round(minRgb.r + (midRgb.r - minRgb.r) * t);
          g = Math.round(minRgb.g + (midRgb.g - minRgb.g) * t);
          b = Math.round(minRgb.b + (midRgb.b - minRgb.b) * t);
        } else {
          // Interpolate between mid and max
          const t = (normalizedValue - 0.5) * 2;
          r = Math.round(midRgb.r + (maxRgb.r - midRgb.r) * t);
          g = Math.round(midRgb.g + (maxRgb.g - midRgb.g) * t);
          b = Math.round(midRgb.b + (maxRgb.b - midRgb.b) * t);
        }
      } else {
        // Fallback to simple interpolation
        r = Math.round(minRgb.r + (maxRgb.r - minRgb.r) * normalizedValue);
        g = Math.round(minRgb.g + (maxRgb.g - minRgb.g) * normalizedValue);
        b = Math.round(minRgb.b + (maxRgb.b - minRgb.b) * normalizedValue);
      }
    } else {
      // Simple interpolation between min and max
      r = Math.round(minRgb.r + (maxRgb.r - minRgb.r) * normalizedValue);
      g = Math.round(minRgb.g + (maxRgb.g - minRgb.g) * normalizedValue);
      b = Math.round(minRgb.b + (maxRgb.b - minRgb.b) * normalizedValue);
    }
    
    return rgbToHex(r, g, b);
  };
}

function drawBootstrapValues() {
  const settings = getBootstrapSettings();
  if (!settings.show || !root) return;
  
  // Determine which tab is active
  const activeTab = document.querySelector('.bootstrap-tab.active')?.getAttribute('data-tab') || 'symbol';
  
  // Clear existing bootstrap symbols and text
  const isRadial = (geometry === 'radial');
  const container = isRadial ? gSpin : g;
  container.selectAll('.bootstrap-symbol').remove();
  container.selectAll('.bootstrap-text').remove();
  
  // Support value of each shown branch (the root has none), from the chosen source
  const bootstrapValues = new Map();
  root.eachAfter(node => {
    const v = getSupportValue(node);
    if (v !== null) bootstrapValues.set(node, v);
  });
  updateSupportNote();
  
  if (bootstrapValues.size === 0) return;
  
  // Range filter in percent of the tree's scale (Text > Show all ignores it)
  const filteredValues = new Map();
  bootstrapValues.forEach((value, node) => {
    const pct = supportPercent(value);
    if ((settings.showAll && activeTab === 'text') || (pct >= settings.minRange && pct <= settings.maxRange)) {
      filteredValues.set(node, value);
    }
  });
  
  if (filteredValues.size === 0) return;
  
  // Create bootstrap group (for both symbols and text)
  const bootstrapGroup = container.append('g').attr('class', 'bootstrap-elements');
  if (!isRadial) bootstrapGroup.attr('data-tree-part', '');   // part of the tree drawing (kept during splitter drags)
  
  // Symbol size follows the value: 0% = minimum size, 100% = maximum size (as the legend shows)
  const sizeRange = settings.maxSize - settings.minSize;
  
  filteredValues.forEach((value, node) => {
    // Calculate position on branch
    const position = activeTab === 'text' ? settings.textPosition / 100 : settings.position / 100;
    
    let x, y;
    if (isRadial) {
      // For radial mode, position along the radial line
      const angle = node.a || 0;
      const parentR = node.parent ? node.parent.r || 0 : 0;
      const nodeR = node.r || 0;
      const r = parentR + (nodeR - parentR) * position;
      x = r * Math.cos(angle - Math.PI / 2);
      y = r * Math.sin(angle - Math.PI / 2);
    } else {
      // For rectangular mode, position along the horizontal branch segment
      if (node.parent) {
        const parentX = node.parent.x || 0;  // Parent vertical position
        const nodeX = node.x || 0;          // Node vertical position  
        const parentY = node.parent.y || 0; // Parent horizontal position
        const nodeY = node.y || 0;          // Node horizontal position
        
        // In rectangular trees, the main branch is horizontal (parentY to nodeY)
        // Position along the horizontal branch segment
        x = parentY + (nodeY - parentY) * position;
        y = nodeX; // Keep at the node's vertical level (horizontal branch)
      } else {
        // Root node - use node position directly
        x = node.y || 0;
        y = node.x || 0;
      }
    }
    
    // Apply vertical shift for text
    if (activeTab === 'text') {
      y += settings.verticalShift;
    }
    
    if (activeTab === 'symbol') {
      // Calculate symbol size based on the support value
      const normalizedValue = Math.max(0, Math.min(1, supportPercent(value) / 100));
      const size = settings.minSize + normalizedValue * sizeRange;
      
      // Create symbol based on type
      let symbol;
      switch (settings.symbolType) {
        case 1: // Circle
          symbol = bootstrapGroup.append('circle')
            .attr('cx', x)
            .attr('cy', y)
            .attr('r', size / 2);
          break;
        case 2: // Triangle
          const trianglePath = `M ${x} ${y - size/2} L ${x - size/2} ${y + size/2} L ${x + size/2} ${y + size/2} Z`;
          symbol = bootstrapGroup.append('path')
            .attr('d', trianglePath);
          break;
        case 3: // Square
          symbol = bootstrapGroup.append('rect')
            .attr('x', x - size/2)
            .attr('y', y - size/2)
            .attr('width', size)
            .attr('height', size);
          break;
        case 4: // Star
          const starPath = createStarPath(x, y, size/2, 5);
          symbol = bootstrapGroup.append('path')
            .attr('d', starPath);
          break;
      }
      
      // Apply symbol styling
      symbol.attr('fill', settings.fillColor)
            .attr('stroke', settings.borderColor)
            .attr('stroke-width', settings.borderWidth)
            .attr('class', 'bootstrap-symbol')
            .attr('data-bootstrap-value', value)
            .attr('data-node', node.data ? node.data.name : 'internal');
    } else if (activeTab === 'text') {
      // Format text value: Percent on shows percent of the scale (95%), off a proportion (0.95)
      const pctValue = supportPercent(value);
      let displayValue = settings.percent ? pctValue : pctValue / 100;
      displayValue = +displayValue.toPrecision(12);   // no floating point noise such as 56.99999999999999
      
      if (settings.scientific) {
        displayValue = displayValue.toExponential(settings.rounding);
      } else if (settings.rounding > 0) {
        displayValue = displayValue.toFixed(settings.rounding);
      }
      
      if (settings.percent) {
        displayValue += '%';
      }
      
      // Apply scale factor
      const fontSize = settings.fontSize * settings.scaleFactor;
      
      // Create text element
      const text = bootstrapGroup.append('text')
        .attr('x', x)
        .attr('y', y)
        .attr('font-size', fontSize)
        .attr('fill', settings.fontColor === '#374151' ? 'var(--text)' : settings.fontColor)
        .attr('text-anchor', 'middle')
        .attr('dominant-baseline', 'middle')
        .attr('class', 'bootstrap-text')
        .attr('data-bootstrap-value', value)
        .attr('data-node', node.data ? node.data.name : 'internal')
        .text(displayValue);
      
      // Apply font styling
      if (settings.bold) {
        text.style('font-weight', 'bold');
      }
      if (settings.italic) {
        text.style('font-style', 'italic');
      }
    }
  });
}

function createStarPath(cx, cy, radius, points) {
  const angle = Math.PI / points;
  let path = '';
  for (let i = 0; i < 2 * points; i++) {
    const r = i % 2 === 0 ? radius : radius * 0.5;
    const x = cx + r * Math.cos(i * angle - Math.PI / 2);
    const y = cy + r * Math.sin(i * angle - Math.PI / 2);
    path += (i === 0 ? 'M' : 'L') + x + ' ' + y;
  }
  return path + 'Z';
}

function updateTreeBranchColors() {
  if (!root) return;
  
  const newRingCol = cssVar('--ring') || '#e5e7eb';
  const svg = d3.select('#svg');
  svg.selectAll('.tree-branch').style('stroke', newRingCol);
  svg.selectAll('.ring-colored').style('stroke', newRingCol);
  svg.selectAll('line[stroke="' + (newRingCol === '#d1d5db' ? '#374151' : '#d1d5db') + '"]')
     .style('stroke', newRingCol);
  svg.selectAll('path[stroke="' + (newRingCol === '#d1d5db' ? '#374151' : '#d1d5db') + '"]')
     .style('stroke', newRingCol);
}

function setExpansionBadge(){
  const pct = tipSpacingSel ? (+tipSpacingSel.value||0) : 0;
  if(tipSpacingValEl2) tipSpacingValEl2.textContent = Math.round(pct) + '%';
  if(tipSpacingSlider2 && String(tipSpacingSlider2.value) !== String(pct)) tipSpacingSlider2.value = String(pct);
  if(tipSpacingNum && String(tipSpacingNum.value) !== String(pct)) tipSpacingNum.value = String(pct);
  if(tipSpacingSel){
    const max = +tipSpacingSel.max || 100; const min = +tipSpacingSel.min || 0; const v = +tipSpacingSel.value || 0;
    const fill = ((v - min) / (max - min)) * 100; tipSpacingSel.style.setProperty('--range-fill', fill + '%');
  }
  if(tipSpacingSlider2){
    const max2 = +tipSpacingSlider2.max || 100; const min2 = +tipSpacingSlider2.min || 0; const v2 = +tipSpacingSlider2.value || 0;
    const fill2 = ((v2 - min2) / (max2 - min2)) * 100; tipSpacingSlider2.style.setProperty('--range-fill', fill2 + '%');
  }
}

function onExpansionInput(pct){
  if(!tipSpacingSel) return;
  const v = String(Math.max(0, Math.min(100, +pct||0)));
  tipSpacingSel.value = v;
  if(tipSpacingNum && tipSpacingNum.value !== v) tipSpacingNum.value = v;
  setExpansionBadge();
  
  drawTree();
  updateZoomBounds();
  adjustSvgHeightForExpansion();
}

function onExpansionChange(){
  setExpansionBadge();
  drawTree();
  updateZoomBounds();
  adjustSvgHeightForExpansion();
  
  if(tipSpacingSel && +tipSpacingSel.value === 0) {
    setTimeout(() => {
      onFitToViewRect();
    }, 50);
  }
}

if(tipSpacingSel){
  tipSpacingSel.addEventListener('input', ()=> onExpansionInput(tipSpacingSel.value));
  tipSpacingSel.addEventListener('change', onExpansionChange);
  const updateFill = ()=>{
    const max = +tipSpacingSel.max || 100; const min = +tipSpacingSel.min || 0; const v = +tipSpacingSel.value || 0;
    const pct = ((v - min) / (max - min)) * 100; tipSpacingSel.style.setProperty('--range-fill', pct + '%');
  };
  tipSpacingSel.addEventListener('input', updateFill);
  tipSpacingSel.addEventListener('change', updateFill);
  updateFill();
}
if(tipSpacingSlider2){
  tipSpacingSlider2.addEventListener('input', ()=> onExpansionInput(tipSpacingSlider2.value));
  tipSpacingSlider2.addEventListener('change', onExpansionChange);
  const updateFill2 = ()=>{
    const max = +tipSpacingSlider2.max || 100; const min = +tipSpacingSlider2.min || 0; const v = +tipSpacingSlider2.value || 0;
    const pct = ((v - min) / (max - min)) * 100; tipSpacingSlider2.style.setProperty('--range-fill', pct + '%');
  };
  tipSpacingSlider2.addEventListener('input', updateFill2);
  tipSpacingSlider2.addEventListener('change', updateFill2);
  updateFill2();
}
if(tipSpacingNum){
  tipSpacingNum.addEventListener('input', ()=> onExpansionInput(tipSpacingNum.value));
  tipSpacingNum.addEventListener('change', onExpansionChange);
}
setExpansionBadge();
const btnRect = document.getElementById('btnRect');
const btnRadial = document.getElementById('btnRadial');
if(btnRect){
  btnRect.addEventListener('click', ()=>{
    geometry = 'rect';
    spinDeg = 0; gSpin = null;
    btnRect.classList.add('active');
    btnRadial && btnRadial.classList.remove('active');
    barPaneWidthOverride = null;
    const c = document.getElementById('canvas'); if(c){ c.style.height = ''; }
    
    initializePanels();
    togglePanelCanvasVisibility(true);
    
    // Reset font cache to recalculate with rectangular layout spacing
    if (typeof resetFontTruncationCache === 'function') {
      resetFontTruncationCache();
    }
    
    // drawTree();
    onFitToViewRect();
    syncControls();
  });
}
if(btnRadial){
  btnRadial.addEventListener('click', ()=>{
    geometry = 'radial';
    btnRadial.classList.add('active');
    btnRect && btnRect.classList.remove('active');
    const c = document.getElementById('canvas'); if(c){ c.style.height = ''; }
    
    togglePanelCanvasVisibility(false);
    
    // Reset radial panel widths to trigger initial width decision logic
    if (window.radialPanelSystem) {
      // Clear all width arrays to force recalculation with initial width logic
      window.radialPanelSystem.resetWidths();
      window.radialPanelSystem.sync();
    }
    
    // Reset font cache to recalculate with radial circumference
    if (typeof resetFontTruncationCache === 'function') {
      resetFontTruncationCache();
    }
    
    drawTree();
    centerRadial();
    spinDeg = rotationDegSel ? (+rotationDegSel.value||0) : 0;
    applySpin();
    liveRotDeg  = rotationDegSel ? (+rotationDegSel.value||0) : 0;
    liveOpenDeg = openAngleDegSel ? (+openAngleDegSel.value||0) : 0;
    refreshRadialPositions();
    syncControls();
  });
}

function syncControls(){
  const isRad = (geometry === 'radial');
  document.getElementById('trackWidth').disabled = isRad;
  document.getElementById('metaColumn').disabled = isRad;
  if(expansionRow1){ expansionRow1.style.display = isRad ? 'none' : 'flex'; }
  if(expansionRow2){ expansionRow2.style.display = isRad ? 'none' : 'flex'; }
  if(tipSpacingSel){ tipSpacingSel.disabled = isRad; }
  if(radialControls){ radialControls.style.display = isRad ? 'flex' : 'none'; }
}

syncControls();
(btnRect||btnRadial) && [btnRect,btnRadial].forEach(b=> b && b.addEventListener('click', syncControls));

(function initSidebarAccordion(){
  const side = document.querySelector('.sidepanel');
  if(!side) return;
  const groups = Array.from(side.querySelectorAll(':scope > details'));
  groups.forEach(d => {
    d.addEventListener('toggle', function(){
      if(this.open){
        groups.forEach(other => { if(other !== this) other.open = false; });
      }
    });
  });
})();

function zoomBy(k){
  const expansionSlider = document.getElementById('expansion');
  const expansionValue = expansionSlider ? parseInt(expansionSlider.value) || 0 : 0;
  
  if (expansionValue > 0) {
    return;
  }
  svg.transition().duration(180).call(zoom.scaleBy, k);
}

const zi = document.getElementById('zoomIn'); if(zi) zi.addEventListener('click', ()=> zoomBy(1.25));
const zo = document.getElementById('zoomOut'); if(zo) zo.addEventListener('click', ()=> zoomBy(0.8));

svg.on('dblclick', (e) => {
  e.preventDefault();
  e.stopPropagation();
  e.stopImmediatePropagation();
  return false;
});

let resizeRaf = null;

function scheduleResizeRedraw(){
  if(resizeRaf) return;
  resizeRaf = requestAnimationFrame(()=>{
    resizeRaf = null;
    if(!root) return; // Skip when no tree data (e.g. page reload before tree loaded)
    drawTree();
    if(geometry === 'radial'){
      centerRadial();
    } else {
      const expPct = tipSpacingSel ? (+tipSpacingSel.value||0) : 0;
      if(expPct <= 0){
        onFitToViewRect();
      } else {
        anchorTopLeftPreserveScale();
        try{ updateMetaAddButtonY(); }catch(e){}
        setTimeout(()=>{
          if(isContentFullyVisible()){
            if(tipSpacingSel){ tipSpacingSel.value = '0'; }
            if(tipSpacingNum){ tipSpacingNum.value = '0'; }
            setExpansionBadge();
            onFitToViewRect();
          }
        }, 50);
      }
    }
  });
}

const canvasEl = document.getElementById('canvas');
if(window.ResizeObserver && canvasEl){
  const ro = new ResizeObserver(() => scheduleResizeRedraw());
  ro.observe(canvasEl);
}
window.addEventListener('resize', scheduleResizeRedraw);

// Builds the standalone SVG document used by every export (SVG, PNG, PDF).
function buildExportSvgSource(){
  const svgEl = document.getElementById('svg');
  
  // Create a clone of the SVG for export
  const svgClone = svgEl.cloneNode(true);
  // alignment layers: their boxes as vector shapes (the screen shows them as pictures)
  if (window.tmMsa && tmMsa.vectorize) { try { tmMsa.vectorize(svgClone); } catch (e) { console.warn(e); } }
  // pictures embedded in the drawing: also as xlink:href, the form Illustrator and older
  // programs read (with only href they take the picture data for the name of a linked file)
  svgClone.querySelectorAll('image').forEach(im => {
    const h = im.getAttribute('href');
    if (h && !im.hasAttributeNS('http://www.w3.org/1999/xlink', 'href')) im.setAttributeNS('http://www.w3.org/1999/xlink', 'xlink:href', h);
  });
  // the pinned header of the expanded view goes back to its normal place
  svgClone.querySelectorAll('.pro-sticky-header').forEach(n => n.removeAttribute('transform'));
  svgClone.querySelectorAll('.pro-sticky-header-bg').forEach(n => n.remove());
  // axis title buttons and hover boxes are not part of the drawing
  svgClone.querySelectorAll('.axis-ui').forEach(n => n.remove());
  // the data-layer grouping used for incremental redraws is not part of the
  // exported drawing: unwrap it so exports keep their usual structure
  svgClone.querySelectorAll('.data-layer, .layers-container').forEach(wrap => {
    while (wrap.firstChild) wrap.parentNode.insertBefore(wrap.firstChild, wrap);
    wrap.remove();
  });
  // colours given as var(--name) references in inline styles (theme colours that
  // follow the theme on screen) become real colours, as attribute references do
  {
    const rootStyle = getComputedStyle(document.documentElement);
    const resolveVars = (v) => v.replace(/var\(\s*(--[\w-]+)\s*(?:,\s*([^)]*))?\)/g, (m, name, fb) => (rootStyle.getPropertyValue(name).trim() || (fb || '').trim() || m));
    svgClone.querySelectorAll('[style*="var("]').forEach(el => {
      const st = el.style;
      for (let i = st.length - 1; i >= 0; i--) {
        const prop = st[i], val = st.getPropertyValue(prop);
        if (val.indexOf('var(') >= 0) st.setProperty(prop, resolveVars(val), st.getPropertyPriority(prop));
      }
    });
  }
  
  // Helper function to resolve CSS variables
  const resolveCSSVariable = (value) => {
    if (!value || !value.startsWith('var(')) return value;
    
    // Get CSS variable value from document root
    const root = document.documentElement;
    const varName = value.match(/var\(--([^)]+)\)/)?.[1];
    if (!varName) return value;
    
    const resolvedValue = getComputedStyle(root).getPropertyValue(`--${varName}`).trim();
    return resolvedValue || value;
  };
  
  // Helper function to convert hex color to RGB
  const hexToRgb = (hex) => {
    if (!hex) return null;
    
    // Remove # if present
    hex = hex.replace('#', '');
    
    // Handle 3-digit hex
    if (hex.length === 3) {
      hex = hex.split('').map(char => char + char).join('');
    }
    
    // Handle 6-digit hex
    if (hex.length === 6) {
      const r = parseInt(hex.substr(0, 2), 16);
      const g = parseInt(hex.substr(2, 2), 16);
      const b = parseInt(hex.substr(4, 2), 16);
      return { r, g, b };
    }
    
    return null;
  };
  
  // Helper function to get computed style and resolve CSS variables
  const getResolvedStyle = (element) => {
    const style = window.getComputedStyle(element);
    return {
      fill: resolveCSSVariable(style.fill),
      stroke: resolveCSSVariable(style.stroke),
      strokeWidth: style.strokeWidth,
      strokeDasharray: style.strokeDasharray,
      backgroundColor: resolveCSSVariable(style.backgroundColor),
      color: resolveCSSVariable(style.color),
      fontSize: style.fontSize
    };
  };
  
  // Remove elements that shouldn't be exported
  // 1. Remove splitter lines, symbols, and hit areas
  svgClone.querySelectorAll('.svg-splitter, .svg-splitter-symbol, .svg-splitter-hit-area, .svg-splitters').forEach(el => el.remove());
  
  // 2. Remove hover tooltips and interactive elements
  svgClone.querySelectorAll('.tooltip, .hover-tooltip, .meta-click').forEach(el => el.remove());
  
  // 3. Remove debug elements
  svgClone.querySelectorAll('[data-debug-color]').forEach(el => el.remove());
  
  // 4. Remove highlight boxes that appear on hover (df-leaf-highlight)
  svgClone.querySelectorAll('.df-leaf-highlight').forEach(el => el.remove());
  
  // 5. Remove label highlight backgrounds only if they're transparent (no highlight data)
  svgClone.querySelectorAll('.label-highlight-bg').forEach(el => {
    const opacity = el.getAttribute('opacity');
    const fill = el.getAttribute('fill');
    
    // Only remove if opacity is 0 or fill is transparent (no highlight data)
    if ((opacity && parseFloat(opacity) === 0) || !fill || fill === 'transparent' || fill === 'none') {
      el.remove();
    } else {
      // Fix styling for visible highlight boxes
      const resolvedFill = resolveCSSVariable(fill);
      if (resolvedFill && resolvedFill !== 'none' && resolvedFill !== 'transparent') {
        el.setAttribute('fill', resolvedFill);
      }
      // Keep the opacity attribute - it works correctly in Adobe Illustrator
      el.setAttribute('opacity', opacity);
    }
  });
  
  // 6. Fix highlight boxes - convert CSS classes to inline styles
  // Look for rect elements with highlight-related attributes
  svgClone.querySelectorAll('rect').forEach(rect => {
    const fill = rect.getAttribute('fill');
    const opacity = rect.getAttribute('opacity');
    const stroke = rect.getAttribute('stroke');
    
    // Check if this is a highlight box (has opacity around 0.15, like box plots)
    if (opacity && parseFloat(opacity) > 0.1 && parseFloat(opacity) < 0.2) {
      const resolvedFill = resolveCSSVariable(fill);
      const resolvedStroke = resolveCSSVariable(stroke);
      
      if (resolvedFill && resolvedFill !== 'none' && resolvedFill !== 'transparent') {
        rect.setAttribute('fill', resolvedFill);
      }
      if (resolvedStroke && resolvedStroke !== 'none' && resolvedStroke !== 'transparent') {
        rect.setAttribute('stroke', resolvedStroke);
      }
      
      // Keep the opacity attribute - it works correctly in Adobe Illustrator
      rect.setAttribute('opacity', opacity);
    }
  });
  
  // 7. Fix scale bars - ensure they have proper styling
  // Target scale bar groups by their IDs (df-scale-*, chart-scale-*, and tree-scale)
  svgClone.querySelectorAll('[id^="df-scale-"], [id^="chart-scale-"], [id="tree-scale"]').forEach(scaleGroup => {
    // Fix all path and line elements in scale bars
    scaleGroup.querySelectorAll('path, line').forEach(element => {
      const strokeColor = '#000000'; // Use black for SVG export
      const strokeWidth = '2px';
      
      element.setAttribute('stroke', strokeColor);
      element.setAttribute('stroke-width', strokeWidth);
      element.setAttribute('opacity', '1.0');
    });
    
    // Fix all text elements in scale bars
    scaleGroup.querySelectorAll('text').forEach(text => {
      const fillColor = resolveCSSVariable('var(--ring)') || '#000000';
      const fontSize = '12px';
      
      text.setAttribute('fill', fillColor);
      text.setAttribute('font-size', fontSize);
      text.setAttribute('font-weight', 'bold');
    });
  });
  
  // 8. Fix grid lines - ensure they have proper styling
  svgClone.querySelectorAll('.chart-grid line').forEach(line => {
    const strokeColor = resolveCSSVariable('var(--ring)') || '#666666';
    const strokeWidth = '1';
    const strokeDasharray = line.getAttribute('stroke-dasharray');
    
    line.setAttribute('stroke', strokeColor);
    line.setAttribute('stroke-width', strokeWidth);
    if (strokeDasharray && strokeDasharray !== 'none') {
      line.setAttribute('stroke-dasharray', strokeDasharray);
    }
  });
  
  // 9. Fix dataframe grid lines - ensure they have proper styling
  svgClone.querySelectorAll('.dataframe-grid line').forEach(line => {
    const strokeColor = resolveCSSVariable('var(--ring)') || '#666666';
    const strokeWidth = '1';
    const strokeDasharray = line.getAttribute('stroke-dasharray');
    
    line.setAttribute('stroke', strokeColor);
    line.setAttribute('stroke-width', strokeWidth);
    if (strokeDasharray && strokeDasharray !== 'none') {
      line.setAttribute('stroke-dasharray', strokeDasharray);
    }
  });
  
  // 10. Fix chart elements - ensure bars, lines, dots have proper colors
  svgClone.querySelectorAll('.chart-bar, .chart-line, .chart-dot, .chart-box').forEach(element => {
    const style = getResolvedStyle(element);
    const fillColor = style.fill || style.backgroundColor;
    const strokeColor = style.stroke;
    
    if (fillColor && fillColor !== 'none' && fillColor !== 'transparent') {
      element.setAttribute('fill', fillColor);
    }
    if (strokeColor && strokeColor !== 'none' && strokeColor !== 'transparent') {
      element.setAttribute('stroke', strokeColor);
    }
  });
  
  // 10. Fix heatmap titles - ensure they have proper styling
  svgClone.querySelectorAll('[class*="heatmap-title-"] text').forEach(text => {
    const fillColor = resolveCSSVariable('var(--ring)') || '#000000';
    const fontSize = '12px';
    
    text.setAttribute('fill', fillColor);
    text.setAttribute('font-size', fontSize);
    text.setAttribute('font-weight', 'bold');
  });
  
  // 11. Fix all text elements to ensure proper styling
  svgClone.querySelectorAll('text').forEach(text => {
    const style = getResolvedStyle(text);
    const fillColor = style.fill || style.color || '#000000';
    const fontSize = style.fontSize;
    
    text.setAttribute('fill', fillColor);
    if (fontSize) {
      text.setAttribute('font-size', fontSize);
    }
  });
  
  // 12. Fix all path elements (tree branches, etc.)
  svgClone.querySelectorAll('path').forEach(path => {
    const style = getResolvedStyle(path);
    const strokeColor = style.stroke;
    const strokeWidth = style.strokeWidth;
    const fillColor = style.fill;
    
    if (strokeColor && strokeColor !== 'none' && strokeColor !== 'transparent') {
      path.setAttribute('stroke', strokeColor);
    }
    if (strokeWidth && strokeWidth !== '0px') {
      path.setAttribute('stroke-width', strokeWidth);
    }
    if (fillColor && fillColor !== 'none' && fillColor !== 'transparent') {
      path.setAttribute('fill', fillColor);
    }
  });
  
  // 13. Fix all rect elements
  svgClone.querySelectorAll('rect').forEach(rect => {
    const style = getResolvedStyle(rect);
    const fillColor = style.fill || style.backgroundColor;
    const strokeColor = style.stroke;
    const strokeWidth = style.strokeWidth;
    
    if (fillColor && fillColor !== 'none' && fillColor !== 'transparent') {
      rect.setAttribute('fill', fillColor);
    }
    if (strokeColor && strokeColor !== 'none' && strokeColor !== 'transparent') {
      rect.setAttribute('stroke', strokeColor);
    }
    if (strokeWidth && strokeWidth !== '0px') {
      rect.setAttribute('stroke-width', strokeWidth);
    }
  });
  
  // 14. Fix all circle elements
  svgClone.querySelectorAll('circle').forEach(circle => {
    const style = getResolvedStyle(circle);
    const fillColor = style.fill || style.backgroundColor;
    const strokeColor = style.stroke;
    const strokeWidth = style.strokeWidth;
    
    if (fillColor && fillColor !== 'none' && fillColor !== 'transparent') {
      circle.setAttribute('fill', fillColor);
    }
    if (strokeColor && strokeColor !== 'none' && strokeColor !== 'transparent') {
      circle.setAttribute('stroke', strokeColor);
    }
    if (strokeWidth && strokeWidth !== '0px') {
      circle.setAttribute('stroke-width', strokeWidth);
    }
  });
  
  // 15. Add legends to the exported SVG (positioned below the tree)
  const metadataLegend = document.getElementById('metadataLegend');
  let legendHeight = 0;
  
  // Check if labels are hidden - if so, skip legend export
  const hideLabelsEl = document.getElementById('hideLabels');
  const hideLabels = hideLabelsEl && hideLabelsEl.checked;
  
  if (metadataLegend && metadataLegend.style.display !== 'none') {
    // Helper to resolve CSS variables
    const resolveCSSVar = (value) => {
      if (!value) return value;
      const match = value.match(/var\((--[^,)]+)(?:,\s*([^)]+))?\)/);
      if (match) {
        const varName = match[1];
        const fallback = match[2];
        const resolved = getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
        return resolved || fallback || value;
      }
      return value;
    };
    
    // Get the current bounding box to position legends to the right
    const currentBBox = svgEl.getBBox();
    const legendStartX = currentBBox.x + currentBBox.width + 40; // 40px gap to the right of tree
    const legendStartY = currentBBox.y + 20; // Start near top of tree with margin
    const treeHeight = currentBBox.height; // Track tree height for column breaks
    let currentX = legendStartX;
    let currentY = legendStartY;
    const lineHeight = 22;
    const boxSize = 16;
    const columnWidth = 250; // Width of each legend column
    const columnGap = 30; // Gap between columns
    const textColor = resolveCSSVar('var(--text)') || '#000000';
    const mutedColor = resolveCSSVar('var(--muted)') || '#666666';
    const ringColor = resolveCSSVar('var(--ring)') || '#999999';
    let maxLegendX = legendStartX; // Track rightmost position
    
    // Create a group for all legends
    const legendGroup = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    legendGroup.setAttribute('id', 'exported-legends');
    
    // Helper function to check if we need a new column
    const checkColumnBreak = (itemsNeeded = 1) => {
      const requiredHeight = (itemsNeeded * lineHeight);
      const remainingHeight = (currentBBox.y + treeHeight) - currentY;
      
      if (remainingHeight < requiredHeight && currentY > legendStartY) {
        // Start new column
        currentX += columnWidth + columnGap;
        currentY = legendStartY;
        maxLegendX = Math.max(maxLegendX, currentX + columnWidth);
      }
    };
    
    // Helper function to add a legend section
    const addLegendSection = (titleText, itemsContainerId) => {
      const itemsContainer = document.getElementById(itemsContainerId);
      if (!itemsContainer || itemsContainer.children.length === 0) return;
      
      // Count items first to check if we need a column break
      const itemCount = itemsContainer.children.length;
      checkColumnBreak(itemCount + 2); // +2 for title and spacing
      
      // Add section title
      const title = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      title.setAttribute('x', currentX);
      title.setAttribute('y', currentY);
      title.setAttribute('fill', '#000000');
      title.setAttribute('font-size', '14px');
      title.setAttribute('font-weight', 'bold');
      title.setAttribute('font-family', 'Arial, sans-serif');
      title.textContent = titleText;
      legendGroup.appendChild(title);
      currentY += lineHeight + 5;
      
      // Add legend items
      Array.from(itemsContainer.children).forEach(item => {
        // "By layer" order: the layer's name above its values
        if (item.classList && item.classList.contains('legend-subtitle')) {
          checkColumnBreak(1);
          const st = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          st.setAttribute('x', currentX);
          st.setAttribute('y', currentY);
          st.setAttribute('fill', '#555555');
          st.setAttribute('font-size', '12px');
          st.setAttribute('font-weight', 'bold');
          st.setAttribute('font-family', 'Arial, sans-serif');
          st.textContent = item.textContent;
          legendGroup.appendChild(st);
          currentY += lineHeight;
          return;
        }
        // Look for SVG element (for bootstrap symbols)
        let svgElement = item.querySelector('svg');
        
        // Look for color box with multiple possible selectors
        let colorBox = item.querySelector('.legend-color-box, .sw, span.sw, div.sw');
        
        // If not found, try finding any child with background color
        if (!colorBox) {
          const children = item.querySelectorAll('*');
          for (const child of children) {
            const style = window.getComputedStyle(child);
            const bg = style.backgroundColor;
            if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') {
              colorBox = child;
              break;
            }
          }
        }
        
        // Look for label (could be .legend-label or any text node)
        let labelSpan = item.querySelector('.legend-label, span:last-child');
        let labelText = labelSpan ? labelSpan.textContent : item.textContent;
        
        // Clean up label text (remove color box content if it was included)
        if (colorBox && labelText) {
          labelText = labelText.replace(colorBox.textContent || '', '').trim();
        }
        
        // Handle continuous gene gradient (percent-valued genes)
        if (item.getAttribute('data-legend-type') === 'gene-gradient') {
          checkColumnBreak(1);
          
          let defs = legendGroup.querySelector('defs');
          if (!defs) {
            defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
            legendGroup.insertBefore(defs, legendGroup.firstChild);
          }
          const gradId = `geneGradient${defs.querySelectorAll('linearGradient').length}`;
          const linearGradient = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
          linearGradient.setAttribute('id', gradId);
          linearGradient.setAttribute('x1', '0%');
          linearGradient.setAttribute('y1', '0%');
          linearGradient.setAttribute('x2', '100%');
          linearGradient.setAttribute('y2', '0%');
          const stops = [['0%', item.getAttribute('data-min-color')]];
          if (item.getAttribute('data-mid-enabled') === '1') stops.push(['50%', item.getAttribute('data-mid-color')]);
          stops.push(['100%', item.getAttribute('data-max-color')]);
          stops.forEach(([offset, color]) => {
            const stop = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
            stop.setAttribute('offset', offset);
            stop.setAttribute('stop-color', color);
            linearGradient.appendChild(stop);
          });
          defs.appendChild(linearGradient);
          
          const addText = (x, content) => {
            const t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
            t.setAttribute('x', x);
            t.setAttribute('y', currentY);
            t.setAttribute('fill', '#000000');
            t.setAttribute('font-size', '12px');
            t.setAttribute('font-family', 'Arial, sans-serif');
            t.textContent = content;
            legendGroup.appendChild(t);
          };
          addText(currentX, item.getAttribute('data-lo-label') || '0%');
          const gradientRect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          gradientRect.setAttribute('x', currentX + 26);
          gradientRect.setAttribute('y', currentY - 13);
          gradientRect.setAttribute('width', '120');
          gradientRect.setAttribute('height', '16');
          gradientRect.setAttribute('fill', `url(#${gradId})`);
          gradientRect.setAttribute('stroke', ringColor);
          gradientRect.setAttribute('stroke-width', '1');
          gradientRect.setAttribute('rx', '3');
          legendGroup.appendChild(gradientRect);
          addText(currentX + 152, item.getAttribute('data-hi-label') || '100%');
          addText(currentX + 152 + 8 * Math.max(4, (item.getAttribute('data-hi-label') || '100%').length), item.getAttribute('data-gradient-label') || '');
          
          currentY += lineHeight;
          maxLegendX = Math.max(maxLegendX, currentX + columnWidth);
        }
        // Handle SVG elements (bootstrap symbols)
        else if (svgElement && labelText) {
          // Check if we need to break to a new column for this item
          checkColumnBreak(1);
          
          // Clone the SVG element and position it
          const svgClone = svgElement.cloneNode(true);
          svgClone.setAttribute('x', currentX);
          svgClone.setAttribute('y', currentY - parseInt(svgElement.getAttribute('height')) + 3);
          legendGroup.appendChild(svgClone);
          
          // Draw label text
          const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          text.setAttribute('x', currentX + parseInt(svgElement.getAttribute('width')) + 10);
          text.setAttribute('y', currentY);
          text.setAttribute('fill', '#000000');
          text.setAttribute('font-size', '12px');
          text.setAttribute('font-family', 'Arial, sans-serif');
          text.textContent = labelText.trim();
          legendGroup.appendChild(text);
          
          currentY += lineHeight;
          maxLegendX = Math.max(maxLegendX, currentX + columnWidth);
        }
        // Handle bootstrap color scale (gradient div)
        else if (itemsContainerId === 'bootstrapColorLegendItems' && item.children.length >= 3) {
          // This is a bootstrap color scale item with "0", gradient, "100" structure
          const leftLabel = item.children[0].textContent;
          const gradientDiv = item.children[1];
          const rightLabel = item.children[2].textContent;
          
          // Check if we need to break to a new column for this item
          checkColumnBreak(1);
          
          // Draw left label
          const leftText = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          leftText.setAttribute('x', currentX);
          leftText.setAttribute('y', currentY);
          leftText.setAttribute('fill', '#000000');
          leftText.setAttribute('font-size', '12px');
          leftText.setAttribute('font-family', 'Arial, sans-serif');
          leftText.textContent = leftLabel;
          legendGroup.appendChild(leftText);
          
          // Draw gradient rectangle
          const gradientRect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          gradientRect.setAttribute('x', currentX + 20);
          gradientRect.setAttribute('y', currentY - 15);
          gradientRect.setAttribute('width', '120');
          gradientRect.setAttribute('height', '20');
          gradientRect.setAttribute('fill', 'url(#bootstrapGradient)');
          gradientRect.setAttribute('stroke', ringColor);
          gradientRect.setAttribute('stroke-width', '1');
          gradientRect.setAttribute('rx', '3');
          legendGroup.appendChild(gradientRect);
          
          // Draw right label
          const rightText = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          rightText.setAttribute('x', currentX + 150);
          rightText.setAttribute('y', currentY);
          rightText.setAttribute('fill', '#000000');
          rightText.setAttribute('font-size', '12px');
          rightText.setAttribute('font-family', 'Arial, sans-serif');
          rightText.textContent = rightLabel;
          legendGroup.appendChild(rightText);
          
          // Create gradient definition if it doesn't exist
          if (!legendGroup.querySelector('#bootstrapGradient')) {
            let defs = legendGroup.querySelector('defs');
            if (!defs) {
              defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
              legendGroup.insertBefore(defs, legendGroup.firstChild);
            }
            
            // Get gradient colors from the div's background
            const gradientStyle = window.getComputedStyle(gradientDiv);
            const background = gradientStyle.background || gradientStyle.backgroundImage;
            
            // Create linear gradient
            const linearGradient = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
            linearGradient.setAttribute('id', 'bootstrapGradient');
            linearGradient.setAttribute('x1', '0%');
            linearGradient.setAttribute('y1', '0%');
            linearGradient.setAttribute('x2', '100%');
            linearGradient.setAttribute('y2', '0%');
            
            // Parse gradient colors (simplified - assumes two-color gradient)
            const settings = getBootstrapSettings();
            const minColor = settings.colorMin || '#ff0000';
            const maxColor = settings.colorMax || '#00ff00';
            
            const stop1 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
            stop1.setAttribute('offset', '0%');
            stop1.setAttribute('stop-color', minColor);
            linearGradient.appendChild(stop1);
            
            const stop2 = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
            stop2.setAttribute('offset', '100%');
            stop2.setAttribute('stop-color', maxColor);
            linearGradient.appendChild(stop2);
            
            defs.appendChild(linearGradient);
          }
          
          currentY += lineHeight;
          maxLegendX = Math.max(maxLegendX, currentX + columnWidth);
        }
        // Handle color boxes (existing logic)
        else if (colorBox && labelText) {
          const colorStyle = window.getComputedStyle(colorBox);
          let bgColor = resolveCSSVar(colorStyle.backgroundColor);
          
          // If background color is not set, try background
          if (!bgColor || bgColor === 'rgba(0, 0, 0, 0)' || bgColor === 'transparent') {
            bgColor = resolveCSSVar(colorStyle.background);
          }
          
          // Fallback to a default color
          if (!bgColor || bgColor === 'rgba(0, 0, 0, 0)' || bgColor === 'transparent') {
            bgColor = '#cccccc';
          }
          
          // Check if we need to break to a new column for this item
          checkColumnBreak(1);
          
          // Draw color box
          const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          rect.setAttribute('x', currentX);
          rect.setAttribute('y', currentY - boxSize + 3);
          rect.setAttribute('width', boxSize);
          rect.setAttribute('height', boxSize);
          rect.setAttribute('fill', bgColor);
          rect.setAttribute('stroke', ringColor);
          rect.setAttribute('stroke-width', '1');
          rect.setAttribute('rx', '2');
          legendGroup.appendChild(rect);
          
          // Draw label text
          const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          text.setAttribute('x', currentX + boxSize + 10);
          text.setAttribute('y', currentY);
          text.setAttribute('fill', '#000000');
          text.setAttribute('font-size', '12px');
          text.setAttribute('font-family', 'Arial, sans-serif');
          text.textContent = labelText.trim();
          legendGroup.appendChild(text);
          
          currentY += lineHeight;
          maxLegendX = Math.max(maxLegendX, currentX + columnWidth);
        }
      });
      
      currentY += 10; // Extra spacing between sections
    };
    
    // Add each legend section
    addLegendSection('Gene Legend:', 'legendItems');
    addLegendSection('Heatmap Legend:', 'heatmapLegendItems');
    addLegendSection('Highlight Legend:', 'highlightLegendItems');
    addLegendSection('Clade Legend:', 'cladeLegendItems');
    addLegendSection('Chart Legend:', 'chartLegendItems');
    addLegendSection('Bootstrap Legend:', 'bootstrapSymbolLegendItems');
    addLegendSection('Bootstrap Color Scale:', 'bootstrapColorLegendItems');
    addLegendSection('Alignment residues:', 'msaLegendItems');
    
    // Add the legend group to the SVG clone if it has content
    if (legendGroup.children.length > 0) {
      svgClone.appendChild(legendGroup);
      // Calculate legend width instead of height (positioned to the right)
      legendHeight = maxLegendX - legendStartX + 40; // This is actually width now, variable name kept for compatibility
    }
  }
  
  // 16. Set proper viewBox and dimensions
  const bbox = svgEl.getBBox();
  const width = svgEl.clientWidth;
  const height = svgEl.clientHeight;
  
  // Account for expansion value when setting viewBox bounds
  const expansionSlider = document.getElementById('expansion');
  const expansionValue = expansionSlider ? parseInt(expansionSlider.value) || 0 : 0;
  
  const pad = 0; // remove extra whitespace around drawing
  const INFO_PANEL_PADDING = 0; // no additional right padding
  
  // Calculate bounds based on current content
  let x0 = bbox.x - pad;
  let x1 = bbox.x + bbox.width + pad + INFO_PANEL_PADDING;
  
  // Ensure content fits within viewport bounds
  // If content is narrower than viewport, constrain panning to prevent over-panning
  if (bbox.width < width) {
    // Content is narrower than viewport - limit panning to keep content visible
    const maxPanLeft = Math.max(0, bbox.width - width);
    x0 = Math.min(x0, -maxPanLeft);
    x1 = Math.max(x1, width - maxPanLeft);
  } else if (expansionValue > 0) {
    // Content is wider than viewport and expansion is enabled - add extra padding
    const expansionPadding = Math.min(bbox.width * 0.5, 200); // Limit expansion padding
    x1 += expansionPadding;
  }
  
  // Add legend width to the viewBox (positioned to the right)
  if (legendHeight > 0) {
    x1 += legendHeight; // legendHeight variable actually contains width now
  }
  
  let y0 = bbox.y - pad;
  let y1 = bbox.y + bbox.height + pad;
  
  // Account for vertical expansion - add extra padding below content when expansion is enabled
  if (expansionValue > 0) {
    const verticalExpansionPadding = Math.min(bbox.height * 0.5, 200); // Limit vertical expansion padding
    y1 += verticalExpansionPadding;
  }
  
  // Use the calculated bounds for viewBox
  const viewBoxWidth = x1 - x0;
  const viewBoxHeight = y1 - y0;
  
  svgClone.setAttribute('viewBox', `${x0} ${y0} ${viewBoxWidth} ${viewBoxHeight}`);
  svgClone.setAttribute('width', viewBoxWidth);
  svgClone.setAttribute('height', viewBoxHeight);
  
  // Text had no font in exports, so viewers fell back to a serif font (Times);
  // use a portable sans-serif like the screen (elements that set their own font keep it)
  if (!svgClone.getAttribute('font-family')) svgClone.setAttribute('font-family', 'Helvetica, Arial, sans-serif');

  // 17. Add xmlns if missing
  if (!svgClone.getAttribute('xmlns')) {
    svgClone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  }
  
  // Serialize and download
  const ser = new XMLSerializer();
  let src = ser.serializeToString(svgClone);
  
  // Ensure proper SVG header
  if (!src.match(/^<svg[^>]+xmlns=/)) {
    src = src.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
  }
  return { src, width: viewBoxWidth, height: viewBoxHeight };
}
window.buildExportSvgSource = buildExportSvgSource;

$('#exportSVG').addEventListener('click', ()=>{
  const src = buildExportSvgSource().src;
  
  // Ask user for filename
  let filename = prompt('File name:', 'tree.svg');
  if (filename === null) return;   // cancelled: nothing is saved
  
  // An empty name: the default
  if (filename.trim() === '') {
    filename = 'tree.svg';
  }
  
  // Ensure .svg extension
  if (!filename.toLowerCase().endsWith('.svg')) {
    filename += '.svg';
  }
  
  const blob = new Blob([src], {type: 'image/svg+xml;charset=utf-8'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
  URL.revokeObjectURL(a.href);
});

  document.getElementById('debugToggle')?.addEventListener('click', (ev)=>{
    ev.stopPropagation();
    
    const panels = document.querySelectorAll('.panel');
    
    panels.forEach(panel => {
      const currentBg = panel.style.backgroundColor;
      if (currentBg && currentBg !== 'transparent') {
        panel.style.backgroundColor = 'transparent';
      } else {
        if (panel.classList.contains('panel-tree')) {
          panel.style.backgroundColor = 'rgba(255, 0, 0, 0.2)';
        } else if (panel.classList.contains('panel-labels')) {
          panel.style.backgroundColor = 'rgba(0, 255, 0, 0.2)';
        } else if (panel.classList.contains('panel-dataframe')) {
          panel.style.backgroundColor = 'rgba(0, 0, 255, 0.2)';
        } else if (panel.classList.contains('panel-dataframe-2')) {
          panel.style.backgroundColor = 'rgba(255, 165, 0, 0.2)';
        }
      }
    });
    
    const splitters = document.querySelectorAll('.splitter');
    const svgSplitters = document.querySelectorAll('.svg-splitter, .svg-splitter-symbol');
    
    splitters.forEach(splitter => {
      const debugColor = splitter.dataset.debugColor;
      if (debugColor) {
        const currentBorder = splitter.style.borderColor;
        if (currentBorder && currentBorder !== 'rgba(var(--accent-rgb, 94, 234, 212), 0.1)') {
          splitter.style.borderColor = 'rgba(var(--accent-rgb, 94, 234, 212), 0.1)';
          splitter.style.backgroundColor = 'rgba(var(--accent-rgb, 94, 234, 212), 0.1)';
        } else {
          splitter.style.borderColor = debugColor;
          splitter.style.backgroundColor = debugColor + '20';
        }
      }
    });
    
    svgSplitters.forEach(svgSplitter => {
      const debugColor = svgSplitter.getAttribute('data-debug-color');
      if (debugColor) {
        const currentStroke = svgSplitter.getAttribute('stroke') || svgSplitter.getAttribute('fill');
        if (currentStroke && currentStroke !== 'var(--accent)') {
          if (svgSplitter.tagName === 'line') {
            svgSplitter.setAttribute('stroke', 'var(--accent)');
          } else {
            svgSplitter.setAttribute('fill', 'var(--accent)');
          }
        } else {
          if (svgSplitter.tagName === 'line') {
            svgSplitter.setAttribute('stroke', debugColor);
          } else {
            svgSplitter.setAttribute('fill', debugColor);
          }
        }
      }
    });
    
    // Toggle radial panel backgrounds
    const radialBackgrounds = document.querySelectorAll('.radial-panel-background');
    
    radialBackgrounds.forEach(bg => {
      const currentOpacity = parseFloat(bg.getAttribute('opacity'));
      if (currentOpacity > 0) {
        bg.setAttribute('opacity', '0');
      } else {
        bg.setAttribute('opacity', '0.15');
      }
    });
    
    // Toggle radial center marker
    const radialCenterMarker = document.querySelectorAll('.radial-center-marker');
    radialCenterMarker.forEach(marker => {
      const currentOpacity = parseFloat(marker.getAttribute('opacity'));
      if (currentOpacity > 0) {
        marker.setAttribute('opacity', '0');
      } else {
        marker.setAttribute('opacity', '0.5');
      }
    });
    
    // Toggle radial panel labels
    const radialPanelLabels = document.querySelectorAll('.radial-panel-label');
    radialPanelLabels.forEach(label => {
      const currentOpacity = parseFloat(label.getAttribute('opacity'));
      if (currentOpacity > 0) {
        label.setAttribute('opacity', '0');
      } else {
        label.setAttribute('opacity', '1');
      }
    });
    
    // Toggle radial info text
    const radialInfoText = document.querySelectorAll('.radial-info-text');
    radialInfoText.forEach(text => {
      const currentOpacity = parseFloat(text.getAttribute('opacity'));
      if (currentOpacity > 0) {
        text.setAttribute('opacity', '0');
      } else {
        text.setAttribute('opacity', '1');
      }
    });
});

