document.getElementById('addDataframe')?.addEventListener('click', (ev)=>{
  ev.stopPropagation();
  
  if (ev.target.disabled) {
    return;
  }
  
  // Show the subcard instead of directly opening file dialog
  const addDataframeBtn = document.getElementById('addDataframe');
  const addDataframeSubcard = document.getElementById('addDataframeSubcard');
  
  if(addDataframeBtn && addDataframeSubcard){
    const isVisible = addDataframeSubcard.style.display !== 'none';
    
      if (!isVisible) {
        const btnRect = addDataframeBtn.getBoundingClientRect();
        const sidebar = document.querySelector('aside');
        const sidebarRect = sidebar ? sidebar.getBoundingClientRect() : null;
        
        // Show subcard first to get its dimensions
        addDataframeSubcard.style.display = 'block';
        const subcardHeight = addDataframeSubcard.offsetHeight;
        const subcardWidth = addDataframeSubcard.offsetWidth;
        
        // Calculate button center
        const btnCenterY = btnRect.top + btnRect.height / 2;
        const btnCenterX = btnRect.left + btnRect.width / 2;
        
        // Position subcard relative to sidebar container with scroll compensation
        const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
        const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
        
        // Calculate position relative to document (not viewport) so it moves with scroll
        const subcardTop = btnRect.bottom + scrollTop + 8; // 8px gap below button
        const subcardLeft = btnCenterX - subcardWidth / 2 + scrollLeft; // Center horizontally
        
        addDataframeSubcard.style.left = subcardLeft + 'px';
        addDataframeSubcard.style.top = subcardTop + 'px';
        addDataframeSubcard.style.position = 'absolute'; // Use absolute positioning relative to document
    } else {
      addDataframeSubcard.style.display = 'none';
    }
    
    addDataframeBtn.classList.toggle('active', !isVisible);
  }
});

// Add click handler for the "+ Add Dataframe" option in the subcard
document.getElementById('addDataframeOption')?.addEventListener('click', (ev)=>{
  ev.stopPropagation();
  
  if (ev.target.disabled) {
    return;
  }
  
  // Hide the subcard
  const addDataframeSubcard = document.getElementById('addDataframeSubcard');
  const addDataframeBtn = document.getElementById('addDataframe');
  if(addDataframeSubcard) {
    addDataframeSubcard.style.display = 'none';
  }
  if(addDataframeBtn) {
    addDataframeBtn.classList.remove('active');
  }
  
  // Perform the original addDataframe functionality
  const newFileInput = document.createElement('input');
  newFileInput.type = 'file';
  newFileInput.accept = '.csv,.tsv,.txt';
  newFileInput.style.display = 'none';
  
  newFileInput.addEventListener('change', async (ev) => {
    if (ev.target.files && ev.target.files[0]) {
      const file = ev.target.files[0];
      
      try {
        await handleMetaFile(file);
      } catch (error) {
        setStatus('Error processing metadata file');
      }
      
      newFileInput.value = '';
      
      newFileInput.remove();
    }
  });
  
  document.body.appendChild(newFileInput);
  try {
    newFileInput.focus();
  } catch(e) {}
  newFileInput.click();
});

