// Add scroll event listener to update subcard position when scrolling
window.addEventListener('scroll', () => {
  const addDataframeSubcard = document.getElementById('addDataframeSubcard');
  const addDataframeBtn = document.getElementById('addDataframe');
  
  if (addDataframeSubcard && addDataframeBtn && addDataframeSubcard.style.display !== 'none') {
    const btnRect = addDataframeBtn.getBoundingClientRect();
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
    
    // Update subcard position to follow the button
    const subcardWidth = addDataframeSubcard.offsetWidth;
    const btnCenterX = btnRect.left + btnRect.width / 2;
    
    const subcardTop = btnRect.bottom + scrollTop + 8; // 8px gap below button
    const subcardLeft = btnCenterX - subcardWidth / 2 + scrollLeft; // Center horizontally
    
    addDataframeSubcard.style.left = subcardLeft + 'px';
    addDataframeSubcard.style.top = subcardTop + 'px';
  }
});

