if (copySelectedFeaturesBtn) {
  // Ensure correct initial state on load
  updateCopySelectedFeaturesButtonVisibility();
  copySelectedFeaturesBtn.addEventListener('click', async () => {
    try {
      const selected = getSelectedGenesForCopy();
      if (!selected.length) {
        showNotification('No gene selected', 'error');
        return;
      }

      // Only copy rows for accessions that are currently visible in the tree (i.e., not dropped)
      const visibleAccessionKeys = root
        ? new Set(root.leaves()
            .filter(leaf => !leaf._removedAsDuplicate && !droppedNodes.has(leaf))
            .map(leaf => normalizeAccession(leaf.data.name)))
        : new Set();

      const rowsToCopy = [];
      const columnOrder = [];
      const columnSet = new Set();

      selected.forEach(({ dataframeId, gene }) => {
        const df = dataframes && dataframes.get ? dataframes.get(dataframeId) : null;
        if (!df || !df.meta || !df.meta.rows || !df.meta.columns) return;
        const meta = df.meta;
        const { geneCol, moleculeCol } = getDataframeColumnIndices(meta);

        // Build unified column order across selected dataframes
        meta.columns.forEach(c => {
          if (c && c.trim() && !columnSet.has(c)) {
            columnSet.add(c);
            columnOrder.push(c);
          }
        });

        meta.rows.forEach(row => {
          if (!row) return;
          // Filter to visible accessions only
          const accKey = normalizeAccession(row[moleculeCol]);
          if (visibleAccessionKeys.size && !visibleAccessionKeys.has(accKey)) return;

          if (String(row[geneCol]) === String(gene)) {
            rowsToCopy.push(row);
          }
        });
      });

      if (!rowsToCopy.length) {
        showNotification('No rows found for selected gene(s)', 'error');
        return;
      }

      // Use strict TSV with real TABs and CRLF line endings for best compatibility (Excel/Sheets)
      const TAB = '\t';
      const NL = '\r\n';
      const colsOut = (columnOrder.length ? columnOrder : ['molecule', 'gene']);
      const tsvEscape = (v) => {
        if (v === undefined || v === null) return '';
        // Prevent embedded tabs/newlines from breaking column separation
        return String(v).replace(/\r?\n/g, ' ').replace(/\t/g, ' ');
      };

      const header = colsOut.join(TAB);
      const body = rowsToCopy.map(row => colsOut.map(col => tsvEscape(row[col])).join(TAB)).join(NL);
      const tsv = header + NL + body + NL;

      await navigator.clipboard.writeText(tsv);
      showNotification(`Copied ${rowsToCopy.length} row(s) for ${selected.length} selected gene(s)`, 'success');
    } catch (error) {
      console.error('Error copying selected features:', error);
      showNotification('Failed to copy to clipboard', 'error');
    }
  });
}

