(function initTheme(){
  const key = 'ptree-theme';
  // Storage can be unavailable (e.g. blocked for file:// pages); never let that stop the app
  let saved = null;
  try { saved = localStorage.getItem(key); } catch (_) { /* ignore */ }
  const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  const theme = saved || (prefersDark ? 'dark' : 'light');
  document.documentElement.setAttribute('data-theme', theme);
  
  if (root) {
    updateTreeBranchColors();
  }
  
  const tgl = document.getElementById('themeToggle');
  if(tgl){
    tgl.checked = theme === 'dark';
    tgl.addEventListener('change', ()=>{
      const t = tgl.checked ? 'dark' : 'light';
      document.documentElement.setAttribute('data-theme', t);
      try { localStorage.setItem(key, t); } catch (_) { /* ignore */ }
      
      // (no updateTreeBranchColors() first: drawTree recreates every branch in the new
      // colours, and recolouring the old ones forced a restyle of the whole drawing)
      drawTree();
    });
  }
})();

