function getSidebarDataframeOrder(){
  const cards = document.querySelectorAll('.dataframe-panel[data-dfid]');
  return Array.from(cards).map(el => +el.getAttribute('data-dfid')).filter(n => !Number.isNaN(n));
}

function reorderDataframesMap(order){
  if(!(window.dataframes instanceof Map)) return;
  const newMap = new Map();
  order.forEach(id => { if(dataframes.has(id)) newMap.set(id, dataframes.get(id)); });
  dataframes.forEach((val, key) => { if(!newMap.has(key)) newMap.set(key, val); });
  window.dataframes = newMap;
}

function syncPanelsToSidebarOrder(){
  try{
    const order = getSidebarDataframeOrder();
    if(!order || order.length === 0) return;
    reorderDataframesMap(order);
    if(typeof updatePanelPositions === 'function') updatePanelPositions();
    if(typeof updateSplitterPositions === 'function') updateSplitterPositions();
    if(typeof updatePanelHeights === 'function') updatePanelHeights();
    // if(typeof drawTree === 'function') drawTree();
    // console.log('drawTree in syncPanelsToSidebarOrder');
  }catch(err){ console.error('Failed to sync panels order:', err); }
}

function renumberDataframeCards(){
  const addBtnWrap = document.getElementById('addDataframeContainer');
  if(!addBtnWrap || !addBtnWrap.parentNode) return;
  const container = addBtnWrap.parentNode;
  const cards = Array.from(container.querySelectorAll(':scope > details.dataframe-panel'));

  cards.forEach((card, idx) => {
    const newId = idx + 1;

    card.setAttribute('data-dfid', String(newId));
    card.id = `dataframeCard${newId}`;

    const summary = card.querySelector('summary[id^="dataframeSummary"]') || card.querySelector('summary');
    if(summary) summary.id = `dataframeSummary${newId}`;

    const title = card.querySelector('[id^="dataframeTitle"]');
    if(title){
      title.id = `dataframeTitle${newId}`;
      title.textContent = `Dataframe ${newId}`;
    }

    const delBtn = card.querySelector('button[id^="deleteDataframe"]');
    if(delBtn){ delBtn.id = `deleteDataframe${newId}`; }

    const geneList = card.querySelector('[id^="geneList"]');
    if(geneList) geneList.id = `geneList${newId}`;
    const operonList = card.querySelector('[id^="operonList"]');
    if(operonList) operonList.id = `operonList${newId}`;

    const alignCard = card.querySelector('[id^="alignCard"]');
    if(alignCard) alignCard.id = `alignCard${newId}`;
    const alignEnable = card.querySelector('input[id^="metaAlignEnable"]');
    if(alignEnable) alignEnable.id = `metaAlignEnable${newId}`;
    const alignGene = card.querySelector('select[id^="metaAlignGene"]');
    if(alignGene) alignGene.id = `metaAlignGene${newId}`;
    card.querySelectorAll('input[name^="metaAlignType"]').forEach((r)=>{
      const v = r.value; r.name = `metaAlignType${newId}`; r.value = v; // preserve value
    });
  });
}

(function installDataframeOrderHooks(){
  const side = document.querySelector('.sidepanel');
  if(!side) return;
  function pruneDataframePlaceholders(keep = 'last'){
    const nodes = side.querySelectorAll('.dataframe-placeholder, .df-dropzone');
    if(nodes.length <= 1) return nodes[0] || null;
    const arr = Array.from(nodes);
    const survivor = (keep === 'first') ? arr[0] : arr[arr.length - 1];
    arr.forEach(n => { if(n !== survivor) n.remove(); });
    return survivor;
  }
  
  function clearAllDataframePlaceholders(){
    side.querySelectorAll('.dataframe-placeholder, .df-dropzone').forEach(n => n.remove());
  }

  const dfPlaceholderObserver = new MutationObserver((mutations)=>{
    let touched = false;
    for(const m of mutations){
      if(m.type === 'childList' && (m.addedNodes && m.addedNodes.length)){
        touched = true; break;
      }
    }
    if(touched) pruneDataframePlaceholders('last');
  });
  try{ dfPlaceholderObserver.observe(side, {childList:true, subtree:true}); }catch(_){/* ignore */}
  pruneDataframePlaceholders('last');
  side.addEventListener('drop', (e)=>{
    if(e.target && e.target.closest && e.target.closest('.dataframe-panel')){
      pruneDataframePlaceholders('last');
      setTimeout(() => {
        syncPanelsToSidebarOrder();
        renumberDataframeCards();
        clearAllDataframePlaceholders();
      }, 0);
    }
  }, true);
  side.addEventListener('dragend', (e)=>{
    if(e.target && e.target.closest && e.target.closest('.dataframe-panel')){
      pruneDataframePlaceholders('last');
      setTimeout(() => {
        syncPanelsToSidebarOrder();
        renumberDataframeCards();
        clearAllDataframePlaceholders();
      }, 0);
    }
  }, true);
  side.addEventListener('dragover', ()=>{ pruneDataframePlaceholders('last'); }, true);
  side.addEventListener('dragstart', (e)=>{
    if(e.target && e.target.closest && e.target.closest('.dataframe-panel')){
      pruneDataframePlaceholders('last');
    }
  }, true);
})();

